  "một lần": "一次",
  "Hằng ngày": "每日",
  "mỗi ngày": "每天",
  "Hằng tuần": "每周",
  "mỗi tuần": "每周",
  "Bạc, Hồn Thạch": "银两、魂石",
  "Hằng tháng": "每月",
  "mỗi tháng": "每月",
  "Bạc, Hồn Thạch, Nguyên Bảo": "银两、魂石、元宝",
  "Việc được chọn theo cấp người chơi; chỉ tiêu và thưởng co giãn theo đó.": "任务依玩家等级选定；目标与奖励随之伸缩。",
  "Phi Cáp Đài": "飞鸽台",
  "Trung tâm thông báo.": "通知中心。",
  "Gom mọi sự kiện xảy ra khi người chơi vắng mặt: hoạt động hoàn tất, vật phẩm hiếm, đệ tử phá cảnh, tin Tiên Minh, sự kiện giang hồ.": "汇集玩家不在时发生的一切：活动完成、稀有物品、弟子破境、仙盟消息、江湖大事。",
  "Thông báo có thưởng lĩnh trực tiếp tại chỗ. Chấm xanh trên chuông báo còn tin chưa đọc.": "附奖励的通知可当场领取。铃铛上的绿点表示尚有未读消息。",
  "Phong Vân Bảng": "风云榜",
  "Bảng xếp hạng toàn giang hồ.": "全江湖排行榜。",
  "Xếp hạng theo Tổng Lv, theo từng nghề, và theo Chiến Lực.": "依总等级、各职业与战力分别排名。",
  "Giang hồ có sẵn 200 cao thủ mô phỏng: họ lên cấp, đổi hoạt động và đổi vùng theo thời gian thực, nên thứ hạng thay đổi liên tục.": "江湖中有 200 位模拟高手：他们即时升级、更换活动与区域，排名因此不断变动。",
  "Mọi tài khoản đứng chung <b>một giang hồ</b>. Cùng một lúc, ai mở Phong Vân Bảng cũng thấy đúng những người ấy.": "所有帐号同处<b>一个江湖</b>。同一时刻，任何人打开风云榜看到的都是同一批人。",
  "Cứ khoảng <b>46 giờ</b> lại có một người nhập giang hồ. Ai đã ở đủ <b>365 ngày</b> thì ẩn cư, rời bảng.": "约每<b>46 小时</b>就有一人踏入江湖。待满<b>365 天</b>者归隐，退出榜单。",
  "Nhờ vậy lúc nào cũng có người mới chân ướt chân ráo để đua, chứ bảng không toàn cao thủ.": "因此榜上总有初出茅庐的新人可较量，而非清一色高手。",
  "Riêng <b>10 lão làng</b> không ẩn cư. Họ ở lại mãi, giữ chỗ đỉnh bảng.": "唯独<b>10 位元老</b>不归隐。他们永远留守，稳坐榜首。",
  "Danh Sĩ": "名士",
  "20 nhân vật có tiểu sử và quan hệ.": "20 位人物，各有生平与关系。",
  "<b>20 Danh Sĩ</b> là lớp nhân vật mô phỏng sâu nhất: mỗi người có xuất thân, môn phái, mạch đời, tâm trạng và quan hệ với nhau.": "<b>20 位名士</b>是模拟最深的人物层：每人皆有出身、门派、人生轨迹、心境与彼此关系。",
