  "Võ Đạo Tông Sư": "武道宗师",
  "Chiến Đấu đạt cảnh giới đại thành — võ học thông thần.": "战斗臻于大成——武学通神。",
  "Phủ Thánh": "斧圣",
  "Đốn Củi đăng phong tạo cực — một phủ khai sơn.": "伐木登峰造极——一斧开山。",
  "Khoáng Thần": "矿神",
  "Đào Khoáng thấu địa tầm long — moi tận kim nguyên.": "采矿透地寻龙——掘尽金源。",
  "Ngư Ẩn Tông Sư": "渔隐宗师",
  "Câu Cá đạt thần cảnh — buông câu kinh động thuỷ cung.": "钓鱼臻于神境——垂纶惊动水宫。",
  "Luyện Kim Thánh Thủ": "冶炼圣手",
  "Luyện Kim hoả hầu viên mãn — quặng thô thành tinh.": "冶炼火候圆满——粗矿成精。",
  "Ngự Trù": "御厨",
  "Nấu Ăn đạt thần thủ — sơn hào hải vị tuỳ tâm.": "烹饪臻于神手——山珍海味随心。",
  "Đan Vương": "丹王",
  "Luyện Đan đăng đỉnh — một lò nên tiên đan.": "炼丹登顶——一炉成仙丹。",
  "Thần Binh Tượng": "神兵匠",
  "Rèn Đúc thông huyền — vạn lần tôi luyện thành thần binh.": "锻造通玄——千锤百炼成神兵。",
  "Thiền Tâm Đại Sư": "禅心大师",
  "Thiền Định nhập định viên mãn — tâm như chỉ thuỷ.": "禅定圆满——心如止水。",
  "Lỗ Ban Tái Thế": "鲁班再世",
  "Xây Dựng đạt tuyệt kĩ — lầu son gác tía dựng trong tay.": "建造臻于绝技——朱楼紫阁起于掌中。",
  "Bách Thảo Chân Nhân": "百草真人",
  "Hái Thuốc đến tận cùng — nhìn cỏ biết tính, chạm rễ biết niên.": "采药臻于化境——观草知性，触根知年。",
  "Minh Chủ": "盟主",
  "Phó Minh Chủ": "副盟主",
  "Đường Chủ": "堂主",
  "Hộ Pháp": "护法",
  "Minh Chúng": "盟众",
  "Tân Nhập": "新入",
  "Tổng Đàn": "总坛",
  "Nhà chính. Nâng lên thì chứa được nhiều người hơn, và minh chúng nộp Minh Cống nhanh hơn.": "主殿。升级后可容纳更多人，盟众缴纳盟贡更快。",
  "Binh Khí Khố": "兵器库",
  "Kho vũ khí. Xây tới cấp nào thì ba kĩ năng Công Kích, Phòng Ngự, Sinh Lực học được tới cấp đó.": "兵器之库。建至几级，攻击、防御、生命三项技能便可学至几级。",
  "Tụ Linh Trì": "聚灵池",
  "Ao linh khí. Ai trong minh đi đánh quái cũng được thêm kinh nghiệm.": "灵气之池。盟中人人打怪皆得额外经验。",
  "Minh Khố": "盟库",
  "Kho chung. Chứa được nhiều loại đồ hơn, và minh chúng nộp Bạc về nhiều hơn.": "共用仓库。可存更多种物品，盟众上缴银两更多。",
  "Trảm Yêu Đài": "斩妖台",
  "Đài triệu Yêu Vương. Mỗi tuần gọi một con về cho cả minh xúm vào đánh, cấp càng cao con càng dữ và thưởng càng dày.": "召唤妖王之台。每周召来一头，全盟齐上围攻——等级越高妖王越凶，奖励越厚。",
  "Luyện Đan Phòng": "炼丹房",
  "Phòng luyện đan. Xây tới cấp nào thì bốn quyết kiếm chác — Tham Tài, Lùng Sục, Thổ Mộc, Toạ Quan — học được tới cấp đó.": "炼丹之房。建至几级，贪财、搜刮、土木、坐观四诀便可学至几级。",
  "Tàng Kinh Các": "藏经阁",
  "Gác chứa kinh. Xây tới cấp nào thì bốn quyết tu luyện — Ngộ Đạo, Tụ Hồn, Tầm Bảo, Mục Thú — học được tới cấp đó.": "藏经之阁。建至几级，悟道、聚魂、寻宝、牧兽四诀便可学至几级。",
  "Diễn Võ Trường": "演武场",
  "Sân luyện võ. Minh chúng tập trận quen tay, mỗi tuần ngươi được thêm lượt xuất trận đánh Yêu Vương.": "练武之场。盟众操练娴熟，每周你多得出战妖王的次数。",
  "Phi Cáp Trạm": "飞鸽站",
  "Trạm chim đưa thư. Danh tiếng Tiên Minh bay xa, người tìm tới cửa xin nhập minh dày hơn.": "飞鸽驿站。仙盟声名远扬，登门求入盟者更多。",
  "Thí Kiếm Đài": "试剑台",
  "Đài tỉ kiếm. Minh chúng mài nghề trên đài, ra ngoài chém quái ghi được nhiều điểm Chinh Phạt hơn.": "比剑之台。盟众台上磨剑，外出斩妖多得征伐点数。",
  "Bạc": "银两",
  "Tiêu vào nguyên liệu, đan dược, công cụ và phí Bí Cảnh.": "用于材料、丹药、工具与秘境费用。",
  "Hồn Thạch": "魂石",
  "Tiêu vào linh thạch, đan dược và Linh Thú bậc cao.": "用于灵石、丹药与高阶灵兽。",
  "Nguyên Bảo": "元宝",
  "Tiêu vào dung mạo, ô chứa và đổi tên — không mua được sức mạnh.": "用于容貌、储物格与改名——买不到实力。",
