  "Công cụ không tham gia chiến đấu. Phần cộng của công cụ vào thẳng mẫu số hiệu suất:": "工具不参与战斗。工具加成直接计入效率分母：",
  "Chu kỳ thực = thời gian cơ sở ÷ tổng hệ số hiệu suất": "实际周期 = 基础时间 ÷ 总效率系数",
  "Nguồn: rèn bằng nghề Rèn Đúc, mua ở Thương Điếm, hoặc rơi trong Bí Cảnh. Xem bảng <b>Công Cụ</b> trong Tra Cứu.": "来源：以锻造打造、在商店购买，或于秘境掉落。详见查询中的<b>工具</b>表。",
  "Hành Lý": "行囊",
  "450 vật phẩm, 13 loại.": "450 种物品，共 13 类。",
  "Số vật phẩm": "物品数量",
  "Gỗ": "木材",
