  "Linh Thảo": "灵草",
  "Vật phẩm thường xếp chồng theo mã; trang bị giữ từng bản riêng.": "一般物品依种类堆叠；装备则逐件单独保存。",
  "Trong đó có <b>72 đồ phổ</b> và <b>30 trứng Linh Thú</b>.": "其中包含<b>72 张图谱</b>与<b>30 颗灵兽蛋</b>。",
  "Hành lý đầy làm mọi hoạt động thu hoạch dừng lại.": "行囊满时，所有采集活动停止。",
  "Trưng Bày": "展示",
  "Bảy ô khoe đồ ở Hồ Sơ.": "档案页的七个展示格。",
  "Giá Trưng Bày nằm ở trang <b>Hồ Sơ</b>, ngay trên khối Trang Bị.": "展示架位于<b>档案</b>页，就在装备区块上方。",
  "Treo được ba thứ: <b>trang bị</b>, <b>vật phẩm trong túi</b> và <b>linh thú</b>.": "可展示三类：<b>装备</b>、<b>行囊物品</b>与<b>灵兽</b>。",
  "Bấm một ô trống là mở bảng chọn. Bấm món đã treo là mở thẻ chi tiết của nó.": "点击空格开启选择面板。点击已展示的物品则开启其详情卡。",
  "Nút <b>Sắp Xếp</b> đổi sang chế độ hạ đồ xuống. Bấm <b>Xong</b> để quay lại.": "<b>整理</b>按钮切换为下架模式。点<b>完成</b>返回。",
  "Giá chỉ <b>trỏ tới</b> thứ ngươi đang có. Bán món hay thả linh thú thì ô tự trống.": "展示架仅<b>指向</b>你现有之物。卖出物品或放生灵兽后，该格自动清空。",
  "Mỗi thứ chỉ treo được một ô. Treo nó sang ô mới thì ô cũ tự nhường chỗ.": "每件物品仅占一格。移展至新格时，旧格自动腾空。",
  "Trưng Bày thuần trang trí — không cộng một điểm chỉ số nào.": "展示纯属装饰——不加任何一点属性。",
  "Động Phủ": "洞府",
  "Nới trần ngoại tuyến và mở công trình tiện ích.": "提升离线上限并开放功能建筑。",
  "Chức năng": "功能",
  "Chi tiết": "详情",
  "Nới trần ngoại tuyến": "提升离线上限",
  "Bậc nhà càng cao, số giờ tính bù càng nhiều": "屋舍等阶越高，补算时数越多",
  "Công trình tiện ích": "功能建筑",
  "Xây bằng Bạc và nguyên liệu, mất thời gian thực": "以银两与材料建造，耗费真实时间",
  "Cửa vào Thiên Cơ Các": "天机阁入口",
  "Các trò nhỏ đặt tại đây": "小游戏皆设于此",
  "Công trình có <b>độ bền</b> giảm dần theo thời gian. Công trình hỏng ngừng tác dụng cho tới khi sửa; phí sửa thấp hơn phí xây mới.": "建筑的<b>耐久</b>会随时间下降。损坏的建筑在修复前失效；修缮费低于新建费。",
  "Danh Sách Nghề": "职业一览",
  "10 nghề, trần cấp 100 mỗi nghề.": "10 种职业，每种等级上限 100。",
  "Việc": "工作",
  "Chặt Cây": "砍树",
  "Khai Khoáng": "开矿",
  "Thái Dược": "摘药",
  "Luyện Kim": "冶炼",
  "Luyện Quặng": "炼矿",
  "Nấu Ăn": "烹饪",
  "Luyện Đan": "炼丹",
  "Luyện Dược": "炼药",
  "Rèn Đúc": "锻造",
  "Rèn Binh Khí": "锻造兵器",
  "Thiền Định": "禅定",
  "Tĩnh Tọa": "静坐",
  "Xây Dựng": "建造",
  "Doanh Tạo": "营造",
  "Mỗi nghề có cấp và kinh nghiệm riêng, trần 100. Mở nghề mới cần Tổng Lv đủ và một khoản Bạc; cứ mỗi 80 Tổng Lv mở thêm một nghề, chi phí tăng dần.": "每种职业有独立等级与经验，上限 100。开启新职业需足够总等级与一笔银两；每 80 总等级可多开一职，费用递增。",
  "Thu Hoạch & Chế Tạo": "采集与制作",
  "Công thức chu kỳ và các nguồn hiệu suất.": "周期公式与各效率来源。",
  "Các nguồn cùng cộng vào mẫu số": "各来源共同计入分母",
  "Cấp nghề": "职业等级",
  "Công cụ đang gắn": "装配中的工具",
  "Tín Vật từ Đàm Đạo": "谈道信物",
  "Kĩ năng Tiên Minh nhánh nghề": "仙盟职业分支技能",
  "Linh Thạch đang đốt": "燃烧中的灵石",
  "Buff Chinh Phạt của vùng đang đứng": "所在区域的征伐增益",
