  "Không cần nguyên liệu (trừ Câu Cá tốn mồi)": "无需材料（钓鱼除外，需消耗鱼饵）",
  "Nguyên liệu thô, kinh nghiệm nghề": "原料、职业经验",
  "Chế tạo": "制作",
  "Nguyên liệu + đồ phổ": "材料 + 图谱",
  "Vật phẩm thành phẩm, kinh nghiệm nghề": "成品物品、职业经验",
  "Nguyên liệu bậc cao chỉ có ở vùng cấp cao. Có <b>72 đồ phổ</b> trong trò chơi.": "高阶材料仅出现于高等级区域。游戏中共有<b>72 张图谱</b>。",
  "Linh Thạch": "灵石",
  "9 loại, cộng kinh nghiệm / hiệu suất / sản lượng.": "9 种，加成经验 / 效率 / 产量。",
  "Linh Thạch là vật phẩm tiêu hao dùng khi làm nghề. Ba nhánh tác dụng: kinh nghiệm nghề, hiệu suất (rút ngắn chu kỳ), sản lượng mỗi lượt.": "灵石是做职业时使用的消耗品。三类效果：职业经验、效率（缩短周期）、每轮产量。",
  "Mỗi viên phủ một khoảng thời gian hoạt động, hết thì tự đốt viên cùng loại kế tiếp.": "每颗灵石覆盖一段活动时间，耗尽后自动燃烧下一颗同类灵石。",
  "Hết sạch thì hoạt động vẫn chạy, chỉ mất phần cộng thêm.": "全部用完后活动照常进行，仅失去加成。",
  "Bảng <b>Linh Thạch</b> trong Tra Cứu ghi mức cộng của từng viên.": "查询中的<b>灵石</b>表载明每颗的加成。",
  "Đàm Đạo": "谈道",
  "10 mạch truyện, mỗi nghề một bậc thầy.": "10 条故事线，每种职业一位宗师。",
  "Mỗi nghề có một nhân vật bậc thầy và một mạch truyện mở dần theo cấp nghề. Cửa vào nằm tại trang của nghề.": "每种职业各有一位宗师，及一条随职业等级逐步开展的故事线。入口位于该职业的页面。",
  "Hoàn tất mạch truyện của một nghề cấp <b>Tín Vật</b>, cộng hiệu suất cố định cho nghề đó.": "完成某职业的故事线可获<b>信物</b>，为该职业提供固定效率加成。",
  "Vòng Đấu": "战斗循环",
  "Nhịp 8 giây một trận, diễn tự động.": "每 8 秒一战，自动进行。",
  "Chiến đấu diễn tự động. Hệ thống nhàn tu chuẩn hoá mỗi vòng cày là <b>8 giây</b>, tương ứng một trận.": "战斗自动进行。挂机系统将每轮标准化为<b>8 秒</b>，对应一场战斗。",
  "Bộ chiêu đã xếp quyết định thứ tự ra chiêu, mức tiêu Nội Lực và hồi chiêu.": "排好的招式组决定出招顺序、内力消耗与冷却。",
  "Sinh Lực duy trì bằng món ăn và đan dược gắn ở ô tự dùng.": "生命靠自动使用栏中的料理与丹药维持。",
  "Gục thì chuyển sang trạng thái Suy Yếu, hết thời gian mới đánh tiếp. Vật phẩm đã nhận không mất.": "倒下后进入虚弱状态，时间结束才继续作战。已获得的物品不会失去。",
  "Có <b>33 loại quái</b> phân bố trên <b>10 vùng</b>. Chỉ số từng con xem ở bảng <b>Quái</b> trong Tra Cứu.": "共<b>33 种怪物</b>分布于<b>10 个区域</b>。各怪属性详见查询中的<b>怪物</b>表。",
  "Ngũ Hành Khắc Chế": "五行克制",
  "Khắc +30%, bị khắc −20%.": "克制 +30%，被克 −20%。",
  "Năm hệ: <b> ·  ·  ·  · </b>. Ngoài ra có <b>Vô Hệ</b> — đòn không thuộc hệ nào, không chịu và không hưởng khắc chế.": "五行：<b> ·  ·  ·  · </b>。另有<b>无系</b>——不属任何一系的攻击，不受也不享克制。",
  "Vòng khắc: Kim → Mộc → Thổ → Thủy → Hỏa → Kim": "相克循环：金 → 木 → 土 → 水 → 火 → 金",
  "Quan hệ": "关系",
  "Hệ số sát thương": "伤害系数",
  "Đánh vào hệ mình khắc": "攻击己方所克之系",
  "Đánh vào hệ khắc mình": "攻击克制己方之系",
  "Cùng hệ hoặc Vô Hệ": "同系或无系",
  "không đổi": "不变",
  "Có <b>8 môn phái</b> đặt tên cho các nhánh võ học theo hệ. Chọn nhánh không khoá việc học chiêu của nhánh khác.": "有<b>8 个门派</b>为各系武学分支命名。选择分支不会锁住修习其他分支的招式。",
  "Kháng Ngũ Hành": "五行抗性",
  "Trần kháng 50%; Tâm Pháp cho sẵn 20% hệ mình.": "抗性上限 50%；心法自带本系 20%。",
  "Mỗi hệ có một chỉ số kháng riêng, giảm trực tiếp sát thương của hệ đó.": "每系各有一项抗性，直接降低该系伤害。",
  "Mục": "项目",
  "Giá trị": "数值",
  "Trần kháng mỗi hệ": "每系抗性上限",
  "Kháng sẵn có từ Tâm Pháp cho hệ của nó": "心法对本系自带的抗性",
  "Nguồn kháng": "抗性来源",
  "Tâm Pháp": "心法",
  "Dòng phụ trang bị": "装备副词条",
  "Dòng ẩn Bộ Trang": "套装隐藏词条",
  "Đan dược": "丹药",
  "Quái cũng có kháng riêng. Chỉ số kháng từng con ghi trong bảng <b>Quái</b> và <b>Yêu Vương</b> ở Tra Cứu.": "怪物也各有抗性。各怪抗性载于查询中的<b>怪物</b>与<b>妖王</b>表。",
  "Cộng Hưởng Ngũ Hành": "五行共鸣",
  "Cộng thẳng % sát thương cho chiêu ĐÚNG hệ đó.": "只为「正是该系」的招式直接加 % 伤害。",
  "<b>Cộng Hưởng</b> của một hệ là <b>phần trăm sát thương cộng thêm cho những chiêu thuộc đúng hệ ấy</b>. Cộng Hưởng Kim chỉ làm mạnh chiêu hệ Kim, không đụng tới chiêu hệ khác.": "某一系的<b>共鸣</b>是<b>为正属该系的招式追加的伤害百分比</b>。金系共鸣只强化金系招式，不影响其他系的招式。",
  "Sát thương chiêu = sát thương gốc × (1 + Cộng Hưởng của hệ chiêu đó)": "招式伤害 = 基础伤害 × (1 + 该招所属系的共鸣)",
  "Ba nguồn Cộng Hưởng": "共鸣的三个来源",
  "Nguồn": "来源",
  "Cho hệ nào": "加成哪一系",
  "Mức": "幅度",
  "hệ của chính Tâm Pháp": "心法自身之系",
  "Bị động võ học": "武学被动",
  "hệ ghi trên bị động": "被动上标明之系",
  "theo từng bị động": "依各被动而定",
  "Trang bị mang hệ": "带系装备",
  "hệ của món đồ": "该件装备之系",
  "theo từng món": "依各件而定",
  "Dòng ẩn <b>7 món</b> của Bộ Trang cũng đổ vào đây — đó là lý do nó ghi dạng “Cộng Hưởng Kim +30%”.": "套装<b>7 件</b>的隐藏词条也汇入此处——因此它写作「金系共鸣 +30%」。",
  "Khi bộ đồ lệch hệ Tâm Pháp": "套装与心法异系时",
  "Cộng Hưởng <b>không mất đi</b>, nhưng chỉ ăn vào chiêu đúng hệ của nó. Mang Tâm Pháp Hỏa mà mặc bộ cho Cộng Hưởng Kim thì 30% ấy chỉ cộng cho chiêu hệ Kim đang lắp; chiêu hệ Hỏa không nhận gì.": "共鸣<b>不会消失</b>，只是仅作用于同系招式。修火系心法却穿上给金系共鸣的套装，那 30% 只加给已装配的金系招式；火系招式毫无所得。",
  "Ô <b>Cộng Hưởng</b> ở bảng chỉ số chỉ hiện <b>hệ chính</b> (hệ của Tâm Pháp). Các hệ lệch hiện thành chip nhỏ ngay cạnh — nhìn đó để biết mình đang dư Cộng Hưởng ở hệ nào.": "属性面板的<b>共鸣</b>栏仅显示<b>主系</b>（心法之系）。异系数值以小徽章显示在旁——看那里便知自己哪一系还有多余共鸣。",
  "Cộng Hưởng <b>khác Khắc Chế</b>: Khắc Chế so hệ mình với hệ đối thủ, còn Cộng Hưởng chỉ nhìn hệ của chính chiêu mình đánh ra.": "共鸣<b>不同于克制</b>：克制比较己方与对手之系，共鸣只看自己所出招式之系。",
  "Hiệu Ứng Theo Hệ": "各系效果",
  "Mỗi hệ một hiệu ứng, có tỉ lệ và số nhịp riêng.": "每系一种效果，各有触发率与节拍数。",
