  "Thể loại nhàn tu, ba trục phát triển song song.": "闲修类型，三条成长主轴并行。",
  "Tiêu Dao Lục là trò chơi <b>nhàn tu</b> (idle) chạy trên trình duyệt. Người chơi đặt một hoạt động, hoạt động tiếp tục chạy khi đóng trình duyệt, và được tính bù khi mở lại.": "《逍遥录》是一款于浏览器执行的<b>闲修</b>（放置）游戏。玩家设定一项行动，关闭浏览器后行动仍持续进行，重新开启时补算进度。",
  "Không có lớp nhân vật cố định. Ba trục phát triển chạy song song và nuôi lẫn nhau:": "没有固定的角色职业。三条成长主轴并行，彼此相辅相成：",
