  "Một hoạt động tại một thời điểm; tiến độ tính bù khi vắng mặt.": "同一时间仅一项行动；离开期间进度会补算。",
  "Tại mỗi thời điểm chỉ có <b>một hoạt động chính</b>: làm nghề, chiến đấu, di chuyển, hoặc Bí Cảnh. Chọn hoạt động mới sẽ dừng hoạt động cũ.": "同一时间只有<b>一项主要行动</b>：技艺、战斗、移动或秘境。选择新行动会停止旧行动。",
  "Tiến độ khi đóng trình duyệt được tính bù lúc mở lại, giới hạn bởi trần ngoại tuyến.": "关闭浏览器期间的进度会在重开时补算，受离线上限限制。",
  "Trần ngoại tuyến cơ sở 8 giờ, nới thêm theo bậc Động Phủ.": "离线上限基础为 8 小时，随洞府等阶提高。",
  "Kết quả khi treo máy và khi ngồi xem là <b>như nhau</b>. Hai đường thưởng dùng chung hệ số.": "挂机与在线观看的结果<b>完全相同</b>。两条奖励路径共用同一套系数。",
