  "Món rơi hoặc rèn ra là <b>bản riêng</b>: cùng tên nhưng dòng phụ bốc khác nhau. Xem chi tiết từng món ở bảng <b>Trang Bị</b> trong Tra Cứu.": "掉落或锻造的每件装备都是<b>独立个体</b>：同名但副词条各自随机。详见查阅中的<b>装备</b>表。",
  "Dòng Phụ & Cường Hoá": "副词条与强化",
  "21 loại dòng phụ; 10 bậc thỏi cường hoá.": "21 种副词条；强化铸锭共 10 阶。",
  "Dòng phụ bốc ngẫu nhiên từ <b>21 loại</b>. Mỗi ô có bộ trọng số riêng, nên dòng nào ra ở ô nào là cố định theo bảng số. Xem bảng <b>Dòng Phụ</b> trong Tra Cứu để biết khoảng giá trị và ô bốc được.": "副词条自 <b>21 种</b>中随机抽取。每个栏位各有权重表，故哪个栏位出哪些词条由数值表固定。数值范围与可抽栏位详见查阅中的<b>副词条</b>表。",
  "Cường hoá": "强化",
  "Tốn Bạc và thỏi kim loại đúng bậc — có <b>10 bậc thỏi</b>.": "消耗银两与对应阶级的金属铸锭——铸锭共 <b>10 阶</b>。",
  "Thất bại không mất món, chỉ mất phí.": "失败不会失去装备，仅损失费用。",
