  "Trang bị rơi từ quái": "怪物掉落装备",
  "Xác suất rơi trang bị = 0.3% × hệ số thưởng rơi đồ": "装备掉落机率 = 0.3% × 掉宝加成系数",
  "Trọng số khi đã rơi": "掉落时权重",
  "Xác suất tuyệt đối mỗi trận": "每场绝对机率",
  "Quái không rơi Mảnh Trang Bị Hoàng Kim — Mảnh chỉ đến từ thông quan Bí Cảnh Lv 70+ và Yêu Vương Lv 90+.": "怪物不掉落黄金装备碎片——碎片仅来自通关 Lv 70+ 秘境与 Lv 90+ 妖王。",
  "Ở mức cơ sở, kỳ vọng khoảng <b>333 trận</b> một món trang bị.": "以基础机率计，约 <b>333 场</b>战斗可得一件装备。",
  "Bộ Trang": "套装",
  "11 bộ; dòng ẩn mở ở mốc 3, 5, 7 món.": "共 11 套；隐藏词条于 3、5、7 件时开启。",
  "Có <b>11 bộ trang</b>. Mặc đủ số món cùng một bộ mở dòng ẩn tại mốc 3, 5 và 7. Mốc sau bao gồm mốc trước.": "共有 <b>11 套套装</b>。穿满同一套装的件数，即于 3、5、7 件时开启隐藏词条。后一门槛包含前一门槛。",
  "Bộ hạng <b>Bạch Kim</b> ghép từ Mảnh Trang Bị theo đồ phổ bộ; đồ phổ rơi ở Bí Cảnh cấp cao.": "<b>白金</b>级套装以装备碎片按套装图谱拼合；图谱掉落于高阶秘境。",
  "Bảng <b>Bộ Trang</b> trong Tra Cứu ghi đủ dòng ẩn từng mốc, số mảnh mỗi món, và nơi rơi đồ phổ.": "查阅中的<b>套装</b>表载明各门槛隐藏词条、每件所需碎片数与图谱掉落地点。",
