  "Bán nguyên liệu cơ bản, mồi câu, món ăn, và vật phẩm trang trí như ảnh đại diện và ảnh nền hồ sơ.": "出售基础材料、鱼饵、菜肴，以及头像与档案背景等装饰物品。",
