  "Đạt đủ điều kiện thì danh hiệu tự mở khoá.": "达成条件后称号自动解锁。",
  "<b>Chỉ danh hiệu đang đeo mới cộng chỉ số.</b> Mở được nhiều cũng không cộng dồn — mỗi lúc chỉ đeo được một cái.": "<b>只有佩戴中的称号才加属性。</b>解锁再多也不叠加——一次只能佩戴一个。",
