  "Vào <b>Tàng Hiệu Các</b>, bấm một danh hiệu đã mở là đeo. Danh hiệu đang đeo hiện ngay cạnh tên nhân vật.": "进入<b>藏号阁</b>，点选已解锁的称号即可佩戴。佩戴中的称号显示在角色名旁。",
