  "Tiến Lên Trung Quốc": "跑得快",
  "Ba nhà, bộ 48 lá, cược Trù Mã": "三家，48 张牌组，以筹码下注",
  "Cờ Tướng và Ngũ Tử Kỳ dùng chung điểm Kỳ Hồn và danh hiệu Kỳ Nghệ.": "象棋与五子棋共用棋魂点数与棋艺称号。",
  "Toàn Màn Hình": "全萤幕",
  "Sáu bàn 3D đều có nút <b>Toàn Màn Hình</b> ở cột nút bên bàn: bàn phủ kín màn hình, không còn thanh đầu trang hay danh mục. Trên điện thoại, máy tự xoay ngang. Bấm lại — hoặc phím Esc — để thu về.": "六张 3D 棋牌桌都在桌旁按钮栏设有<b>全萤幕</b>按钮：桌面铺满萤幕，不再有顶栏与选单。手机上会自动转为横向。再按一次——或按 Esc 键——即可还原。",
  "Trù Mã — đồng riêng của chiếu bài": "筹码——牌桌专属货币",
  "Ba trò bài — Tiến Lên, Tiến Lên Trung Quốc và Binh Xập Xám — cược bằng <b>Trù Mã</b>, không phải Bạc. Đổi Bạc lấy Trù Mã theo tỉ giá <b>1 đổi 1</b>, và chỉ đổi được một chiều.": "三款纸牌游戏——进升、跑得快与十三水——以<b>筹码</b>下注，而非银两。银两兑换筹码比率<b>1 比 1</b>，且只能单向兑换。",
  "Trù Mã <b>không đổi ngược lại thành Bạc</b>. Nhờ vậy thắng bài không sinh ra Bạc — các trò này cách ly khỏi kinh tế chính, không ảnh hưởng cân bằng cày cuốc.": "筹码<b>不能换回银两</b>。因此赢牌不会产生银两——这些游戏与主经济隔离，不影响修炼平衡。",
