  "Cộng lẻ": "单项加成",
  "Chiến Sĩ": "战士",
  "Thiết cốt cương thân, chính khí ngút trời. Đao thương qua tay hóa sấm sét, lấy cương mãnh phá vạn pháp — chính diện giao phong chẳng chút nao núng.": "铁骨钢身，正气冲天。刀枪过手化雷霆，以刚猛破万法——正面交锋毫不退缩。",
  "+10% Lực Đạo EXP": "力道经验 +10%",
  "+5% Chiến Đấu EXP": "战斗经验 +5%",
  "Ám Vệ": "暗卫",
  "Ẩn thân trong bóng tối, đến đi tựa gió thoảng. Một nhát đoạt mệnh giữa chớp mắt, thân pháp quỷ dị khiến địch chưa kịp thấy bóng đã thân thủ dị xứ.": "匿身暗影，来去如风。眨眼间一击夺命，身法诡异，敌人未见其影已身首异处。",
  "+5% Thân Pháp EXP": "身法经验 +5%",
  "+10% Hiệu suất săn": "狩猎效率 +10%",
  "Rong ruổi chân trời, cung tiễn bất ly thân. Mũi tên rời dây xuyên mây vọng nguyệt — lấy khoảng cách làm khiên, lấy giang hồ làm nhà.": "浪迹天涯，弓箭不离身。离弦之箭穿云望月——以距离为盾，以江湖为家。",
  "+7% Linh Xảo EXP": "灵巧经验 +7%",
  "+8% Hiệu suất săn": "狩猎效率 +8%",
  "Rìu nặng trên vai, sống đời sơn lâm. Mỗi nhát bổ xuống vang động núi rừng, gỗ quý chất đầy — bậc thầy đốn mộc chốn thâm sơn.": "重斧扛肩，栖身山林。每一斧落下震动山野，良木成堆——深山伐木的宗师。",
  "+10% Đốn Củi EXP & Hiệu suất": "伐木经验与效率 +10%",
  "Lăn lộn nơi hầm sâu lòng đất, mắt tinh nhìn thấu mạch khoáng. Búa chim nện đá toé lửa, moi tận long mạch lấy kim ngọc châu báu.": "摸爬于地底深坑，慧眼看穿矿脉。鹤嘴锄敲石迸火，掘尽龙脉取金玉珠宝。",
  "+10% Đào Khoáng EXP & Hiệu suất": "采矿经验与效率 +10%",
  "Ngư Ông": "渔翁",
  "Một cần buông xuống, tĩnh tọa bên sông. Tâm như nước lặng chờ thời — kiên nhẫn đợi một khắc, cá lớn ắt cắn câu.": "一竿垂下，静坐江边。心如止水待时机——耐心守候一刻，大鱼必然上钩。",
  "+10% Câu Cá EXP & Hiệu suất": "钓鱼经验与效率 +10%",
  "Tay dao thớt biến sơn hào hải vị thành cao lương. Lửa đượm hương bay, một bàn tiệc đãi anh hùng thiên hạ, no lòng ấm dạ lữ khách phong trần.": "刀俎之间化山珍海味为佳肴。火旺香飘，一席盛宴款待天下英雄，暖饱风尘旅人。",
  "+10% Nấu Ăn EXP & Hiệu suất": "烹饪经验与效率 +10%",
  "Thợ Luyện Kim": "冶炼师",
  "Đứng giữa lò lửa ngút trời, quặng thô qua tay hóa tinh kim. Nghe hơi nóng mà đoán độ già non, luyện ra thỏi sáng loáng cho bậc thợ rèn.": "立于冲天炉火之间，粗矿过手化精金。听热气而辨火候，炼出亮锭供锻匠之用。",
  "+10% Luyện Kim EXP & Hiệu suất": "冶炼经验与效率 +10%",
  "Ngự Thú Sư": "御兽师",
  "Lòng thông vạn vật, ý thấu muông thú. Thuần phục linh thú sơn lâm làm bạn đồng hành — một tiếng sáo ngân, cả bầy nghe lệnh.": "心通万物，意晓禽兽。驯服山林灵兽为伴——一声笛响，群兽听令。",
  "+10% Ngự Thú EXP": "御兽经验 +10%",
  "Phế Nhân": "废人",
  "Kẻ tu hành gập ghềnh nhất thiên hạ: căn cơ hao tổn, mỗi bước tiến đẫm mồ hôi xương máu. Chỉ dành cho kẻ ngạo nghễ dám thách thức chính số mệnh.": "天下最坎坷的修行者：根基受损，每进一步皆浸血汗。只留给敢向命运挑战的傲骨之人。",
  "-50% MỌI EXP": "全部经验 -50%",
  "Lưu Đày": "流放",
  "Bị giang hồ ruồng bỏ, một thân một bóng bôn tẩu. Không bằng hữu, không giao dịch — chỉ có chính mình và con đường cô độc trải dài phía trước.": "遭江湖遗弃，孤身只影奔走。无朋友，无交易——只有自己与眼前漫长的孤独之路。",
  "Cấm Giao Dịch": "禁止交易",
  "-50% phí Truyền Tống": "传送费 -50%",
  "Ma Chủng": "魔种",
  "Thân mang tà chú thượng cổ, nghịch thiên mà tu. Con đường gian nan bậc nhất thế gian — kẻ nhụt chí chớ dại bước vào, vinh quang chỉ thuộc về kẻ cuồng nhất.": "身负上古邪咒，逆天而修。世间最艰难之路——志弱者切莫踏入，荣耀只属于最疯狂之人。",
  "Lưu Đày + Phế Nhân": "流放 + 废人",
  "Kỹ Năng": "技能",
  "Khổ Tu (Khóa — thử thách cực khó)": "苦修 (锁定 — 极难挑战)",
  "Rìu nặng trên vai, bậc thầy đốn mộc chốn thâm sơn.": "重斧扛肩，深山伐木的宗师。",
  "Khoáng Phu": "矿夫",
  "Mắt tinh nhìn thấu mạch khoáng, moi tận kim ngọc lòng đất.": "慧眼看穿矿脉，掘尽地底金玉。",
  "Tĩnh tọa bên sông, kiên nhẫn đợi một khắc cá lớn cắn câu.": "静坐江边，耐心守候大鱼上钩的一刻。",
  "Trù Sư": "厨师",
  "Tay dao thớt biến sơn hào hải vị thành cao lương.": "刀俎之间化山珍海味为佳肴。",
  "Nghe hơi nóng mà đoán độ già non, luyện quặng thành tinh kim.": "听热气而辨火候，炼矿成精金。",
  "Phối chế đan dược, luyện linh thạch trợ tu.": "调配丹药，炼制灵石助修。",
  "Thiết Tượng": "铁匠",
  "Rèn binh khí, đúc giáp trụ — lửa đượm thép reo.": "锻造兵器，铸造甲胄——火旺钢鸣。",
  "Thiền Sư": "禅师",
  "Tĩnh tâm ngộ đạo, vun bồi nội tâm tịch lặng.": "静心悟道，涵养内心寂静。",
  "Bậc thầy kiến tạo, dựng động phủ vững bền.": "建造宗师，筑就稳固洞府。",
  "Một giỏ trúc lội khắp sơn dã, cỏ nào là thuốc cỏ nào là độc — nhìn là biết.": "一篓竹筐走遍山野，何草为药何草为毒——一眼便知。",
