  "Dùng chiêu → sinh 2 ô Khí": "施放技能 → 生成 2 气格",
  "Mỗi trận 1 lần nối lượt vượt giới hạn": "每场 1 次超上限接续回合",
  "Kiếm Khí Trảm": "剑气斩",
  "Chém 55 sát thương thẳng vào địch và quét sạch một hàng ô ngang trên bàn.": "对敌直劈 55 点伤害，并扫清盘面一整横排。",
  "Khí tụ thành phong — kiếm khai nhất tuyến.": "气聚成锋 — 剑开一线。",
  "Hoán Tinh Di Đẩu": "换星移斗",
  "Đổi chỗ hai ô bất kỳ trên bàn, không cần nằm kề — tự tay xếp combo.": "交换盘面任意两格，无须相邻 — 亲手排出连击。",
  "Dời sao đổi đẩu — càn khôn tại thủ.": "移星换斗 — 乾坤在手。",
  "Huyết Sát": "血煞",
  "Mỗi ô Kiếm trên bàn nổ: mỗi ô gây 4 sát thương và hồi 2 máu cho ngươi, rồi vỡ.": "盘面每个剑格引爆：每格造成 4 点伤害并为你回复 2 点生命，随后碎裂。",
  "Kiếm khát máu tanh — một chém hồi sinh.": "剑渴血腥 — 一斩回生。",
  "Hoàng Kim Nhất Kích": "黄金一击",
  "Mỗi ô Bảo phá được dồn vào kho vàng; xả kho gây sát thương bằng số điểm đã tích — càng gom càng nặng.": "每破一宝格皆存入金库；释放时造成等同累积点数的伤害 — 越积越重。",
  "Vàng ròng đúc kiếm — một vựng nghìn lượng.": "真金铸剑 — 一挥千两。",
  "Ngũ Hành Đại Chuyển": "五行大转",
  "Biến cả vùng 3×3 giữa bàn thành một loại ô ngẫu nhiên — tạo đại combo tức thì.": "将盘面中央 3×3 区域化为同一种随机格 — 瞬间造出大连击。",
  "Ngũ hành đại chuyển — sắc quy nhất thể.": "五行大转 — 色归一体。",
  "Ô Long Giao Tranh": "乌龙交争",
  "Nếu địch có ô Độc: hóa hết thành ô Kiếm và phản độc về địch. Nếu không: gieo Độc lên địch.": "若敌方有毒格：全数化为剑格并将毒反施其身。若无：对敌播毒。",
  "Rồng đen cản ngược — độc phản về nguồn.": "乌龙逆截 — 毒返其源。",
  "Ngưng Sương Quyết": "凝霜诀",
  "Đóng băng địch: bỏ qua đòn đánh kế và lượt rải Độc kế của địch.": "冰封敌人：跳过其下一次攻击与下一轮撒毒。",
  "Sương giăng vạn vật — tĩnh chỉ sát cơ.": "霜笼万物 — 静止杀机。",
  "Ngũ Lôi Chính Pháp": "五雷正法",
  "Giáng 8 sát thương lên mỗi ô đặc biệt rồi kích nổ tất cả, nổ dây chuyền Hợp Bích toàn bàn.": "对每个特殊格降下 8 点伤害并全数引爆，全盘连锁合璧爆发。",
  "Ngũ lôi oanh đỉnh — quần tà tận diệt.": "五雷轰顶 — 群邪尽灭。",
  "Tụ Sa Thành Tháp": "聚沙成塔",
  "Tích Lũy": "积累",
  "Xóa càng nhiều ô trong một đòn, hiệu lực càng tăng vọt (một đòn 6 ô mạnh hơn hẳn hai đòn 3 ô). Tính tối đa 9 ô mỗi đòn.": "一击消除越多格，效果越是暴增 (一次 6 格远胜两次 3 格)。每击最多计 9 格。",
  "Tích cát vi sơn — nhất kích thiên quân.": "积沙为山 — 一击千钧。",
  "Càn Khôn Nghịch Chuyển": "乾坤逆转",
  "Sinh Hóa": "生化",
  "Ô mới rơi xuống thiên về loại kế trong vòng Ngũ Hành (Kiếm, Khí, Bảo, Tâm, Thuẫn), giúp chủ động gom chuỗi liên hoàn.": "新落下的格偏向五行循环的下一种 (剑、气、宝、心、盾)，便于主动串起连环。",
  "Vạn vật tương sinh — diệt một, sinh một.": "万物相生 — 灭一，生一。",
  "Hoá Độc Đại Pháp": "化毒大法",
  "Dụng Độc": "用毒",
  "Mỗi ô Độc của địch ngươi phá được nạp 1 Độc Tinh (tối đa 8). Đòn Kiếm kế cộng +4 sát thương mỗi Độc Tinh rồi xả sạch.": "每破一个敌方毒格储入 1 枚毒精 (至多 8)。下一次剑击每枚毒精 +4 伤害，随后清空。",
  "Độc nhập ta tạng — hoàn lại kẻ gieo.": "毒入我脏 — 还于播毒者。",
  "Kim Cang Hộ Thể": "金刚护体",
  "Mỗi lượt 25% Hộ Thuẫn hiện có dồn thẳng vào đòn Kiếm kế (không hao Hộ Thuẫn) — càng thủ, phản đòn càng nặng.": "每回合当前护盾的 25% 直接灌入下一次剑击 (不消耗护盾) — 守得越厚，反击越重。",
  "Thân như kim thạch — phản chấn bách địch.": "身如金石 — 反震百敌。",
  "Thái Cực Vô Cực": "太极无极",
  "Vận Khí": "运气",
  "Tạo ô đặc biệt được +15 Khí; kích nổ hoặc Hợp Bích +8 Khí. Trần nối lượt liên tiếp tăng từ 2 lên 3.": "造出特殊格 +15 气；引爆或合璧 +8 气。连续接续回合上限由 2 升至 3。",
  "Nhất khí hóa tam thanh — trận trung sinh trận.": "一气化三清 — 阵中生阵。",
  "Thôn trang yên bình, đồng cỏ xanh và nông trại nhỏ.": "宁静村庄，绿野农舍点点。",
  "Rừng già rậm rạp, gió thì thầm giữa tán cây.": "苍苍老林，风在树冠间低语。",
