  "Tuần lộc gạc trắng dẫn đầu đàn, vó nó đạp lên tuyết mà không để lại vết.": "白角驯鹿走在鹿群最前，蹄踏雪上不留痕迹。",
  "Thổ tối thượng + Choáng CHẮC CHẮN": "土之至尊 + 必定晕眩",
  "Mô phỏng thần lực Bàn Cổ khai thiên, giáng xuống một ấn nặng tựa cả dãy núi. Mặt đất nứt toác thành vực, khe nứt rực đỏ như gân dung nham — địch nhân bị chấn cho hồn phách lìa khỏi xác, đứng còn chẳng nổi.": "仿盘古开天神力，降下一印重若群山。大地崩裂成渊，裂缝赤红如熔岩之脉 — 敌人被震得魂飞魄散，站都站不稳。",
  "thạch ấn nặng tựa non cao giáng xuống": "重若高山的石印轰然落下",
  "đất nứt toác, khe sâu rực đỏ dung nham": "大地崩裂，深壑赤红如熔岩",
  "một ấn trấn nhạc, địch ngã quỵ bất động": "一印镇岳，敌人瘫倒不动",
  "Đỉnh cao Hậu Thổ — Choáng CHẮC CHẮN 100%. Khoá cứng địch một hiệp trọn vẹn, dọn đường cho cả bộ liên hoàn.": "后土之巅 — 100%必定晕眩。将敌人整整封锁一回合，为整套连招开路。",
  "Vô Tướng Sát Kiếp": "无相杀劫",
  "Vô Hệ tối thượng — miễn khắc hệ": "无系至尊 — 免疫五行克制",
  "Không hình không tướng, không hệ không khí — chỉ còn thuần một đạo sát ý. Kình lực nén tới cực hạn rồi vỡ ra, không khí rách thành vệt chân không; ngũ hành sinh khắc tới đây thảy đều vô nghĩa.": "无形无相，无系无气 — 只余纯粹一道杀意。劲力压至极限而后迸裂，空气撕成真空之痕; 五行生克至此皆属虚无。",
  "kình lực vỡ ra, không khí rách thành vệt": "劲力迸裂，空气撕裂成痕",
  "một đạo sát ý vô hình quét ngang": "一道无形杀意横扫而过",
  "vô tướng vô sắc, ngũ hành thảy vô dụng": "无相无色，五行皆无用",
  "Đỉnh cao thuần lực — chẳng sợ khắc kháng ngũ hành. Quân bài tẩy khi gặp địch khắc hệ mình.": "纯力之巅 — 不惧五行克抗。遭遇克制己系之敌时的底牌。",
  "+80% sát thương trong 6 hiệp": "6回合内+80%伤害",
  "Thu tâm về một mối, thần giao cùng trời đất. Chân khí quanh thân hoá thành trụ sáng vươn thẳng lên chín tầng mây, vòng thái cực xoay quanh không dứt — trong khoảnh khắc ấy, người chính là thiên địa.": "收心归一，神交天地。周身真气化作光柱直上九霄，太极之环旋转不息 — 那一瞬，人即天地。",
  "trụ sáng vươn thẳng lên chín tầng mây": "光柱直上九霄",
  "vòng thái cực xoay quanh, khí thế áp cả trời": "太极环旋转，气势压苍穹",
  "thần giao thiên địa, một niệm mà vạn pháp tuỳ tâm": "神交天地，一念万法随心",
  "Đỉnh cao tăng ích — gần gấp đôi sát thương. Bật rồi tung Thái A hoặc Viêm Đế, một nhịp định thắng bại.": "增益之巅 — 伤害近乎翻倍。开启后再出太阿或炎帝，一击定胜负。",
  "Lấy hỏa luyện thân, công pháp bạo liệt — càng đánh càng hăng.": "以火炼身，功法暴烈 — 越战越勇。",
  "Hàn Băng Cung": "寒冰宫",
  "Lấy nhu khắc cương, hàn khí trầm ổn — thiên khống chế & bền bỉ.": "以柔克刚，寒气沉稳 — 擅控制 & 持久。",
  "Mô phỏng lẽ sinh trưởng vạn vật — độc khí âm ỉ, tự sinh tự dưỡng.": "仿万物生长之理 — 毒气阴蕴，自生自养。",
  "Chân khí ngưng như kim loại, mũi nhọn vô song — phá giáp, nhất kích tất sát.": "真气凝如金铁，锋芒无双 — 破甲，一击必杀。",
