  "Cương Kim Hộ Thể": "刚金护体",
  "+18% sát thương chiêu Kim": "+18% 金系招式伤害",
  "Vận Cương Kim chân khí hộ thể, da thịt rắn lại tựa kim loại tôi qua lửa. Hệ Kim trong tay người càng thêm sắc, mỗi chiêu vung ra như thần binh vừa khai phong.": "运刚金真气护体，血肉坚如淬火之金。手中金系招式愈发锋锐，每一招挥出皆似新开锋的神兵。",
  "Lợi Nhận Quyết": "利刃诀",
  "+10% Bạo Kích · +20% Sát Thương Bạo Kích": "+10% 暴击 · +20% 暴击伤害",
  "Tâm pháp luyện cho ý niệm sắc bén như mũi nhọn, một lòng tìm tới yếu huyệt. Nhất kích tất sát — đã ra tay là nhắm chỗ hiểm, trúng thì kinh thiên động địa.": "此心法将意念磨得针尖般锐利，一心直取要害。一击必杀——出手便攻致命处，命中则惊天动地。",
  "Thanh Mộc Hộ Thể": "青木护体",
  "+18% sát thương chiêu Mộc": "+18% 木系招式伤害",
  "Mượn sinh khí thảo mộc dưỡng chân nguyên, lục khí tuần hoàn trong người không dứt. Mỗi chiêu Mộc tung ra đều mang sức sống bừng bừng của vạn vật lúc xuân về.": "借草木生气滋养真元，绿气在体内循环不息。每一招木系招式，皆带著万物逢春的蓬勃生机。",
  "Sinh Sinh Bất Tức": "生生不息",
  "giảm 18% Sát Thương phải chịu": "受到伤害减少 18%",
  "Mô phỏng lẽ sinh trưởng của cỏ cây — thân mềm mà dai, gân thịt nuốt bớt lực đòn như cành liễu nuốt gió bão. Sinh cơ bất tuyệt, cong xuống rồi lại vươn, chém mãi không đứt.": "仿效草木生长之理——身柔而韧，筋肉化去来劲，如柳枝吞纳狂风。生机不绝，弯而复起，砍之不断。",
  "Huyền Băng Hộ Thể": "玄冰护体",
  "+18% sát thương chiêu Thủy": "+18% 水系招式伤害",
  "Hàn khí Huyền Băng bao bọc châu thân, lạnh thấu mà trầm ổn vô cùng. Chiêu Thuỷ trong tay người thêm phần âm nhu mà hàn liệt, chạm vào là buốt tới tận xương.": "玄冰寒气裹住周身，寒彻入骨却沉稳无比。手中水系招式愈加阴柔寒冽，一触便冻彻骨髓。",
  "Đại Chu Thiên": "大周天",
  "+25% Nội Lực · +40% hồi Nội Lực": "+25% 内力 · +40% 内力回复",
  "Khai thông đại chu thiên, chân khí lưu chuyển khắp kinh mạch như trăm sông cùng đổ về biển. Nội tức bất tận, tuyệt kỹ tung liên hồi mà khí hải chẳng hề vơi cạn.": "打通大周天，真气流转诸脉，如百川归海。内息不绝，绝技连发而气海不竭。",
  "Viêm Dương Hộ Thể": "炎阳护体",
  "+18% sát thương chiêu Hỏa": "+18% 火系招式伤害",
  "Tẩm Viêm Dương hỏa khí vào da thịt, toàn thân nóng rực như lò bát quái luyện đan. Mỗi chiêu Hỏa đều thêm phần uy mãnh, thiêu rụi tất thảy chắn ngang đường.": "将炎阳火气淬入血肉，周身灼热如炼丹八卦炉。每一招火系招式愈发威猛，焚尽挡路一切。",
  "Phần Thiên Quyết": "焚天诀",
  "+18% Công · −8% Thủ": "+18% 攻击 · −8% 防御",
  "Quyết này dạy lấy công làm thủ, khí thế ngùn ngụt áp đảo cả quần địch. Lao thẳng tấn sát bất chấp phòng bị — kẻ gan nhỏ chớ dại mà học theo.": "此诀教人以攻代守，气势滔天压倒群敌。直进抢杀不顾防备——胆小之辈切莫妄学。",
  "Hậu Thổ Hộ Thể": "厚土护体",
  "+18% sát thương chiêu Thổ": "+18% 土系招式伤害",
  "Dẫn Hậu Thổ trọng kình trầm xuống đan điền, thân vững như non cao bám rễ vào lòng đất. Chiêu Thổ tung ra nặng tựa thiên quân, một kích trấn áp tất cả.": "引厚土重劲沉入丹田，身稳如高山扎根大地。土系招式出手重若千钧，一击镇压一切。",
  "Kim Cương Bất Hoại": "金刚不坏",
  "+22% Thủ · +14% Sinh Lực": "+22% 防御 · +14% 生命",
  "Khổ luyện nhục thân tới cảnh giới kim cương bất hoại, da gân rắn chắc như đá tảng. Vạn kích giáng xuống cũng khó để lại vết, đứng giữa loạn quân như một toà bàn thạch.": "苦炼肉身至金刚不坏之境，皮筋坚如巨岩。万击加身也难留痕，立于乱军之中如一座磐石。",
  "Quân Hành Bộ": "军行步",
  "+10% Công": "+10% 攻击",
  "+10% Thủ": "+10% 防御",
  "+10% Tốc": "+10% 速度",
  "−15% Bạo kích": "−15% 暴击",
  "Tứ bình bát ổn, công thủ toàn diện. Mạnh đều mọi mặt nhưng thiếu sát chiêu hiểm — gần như không bạo kích.": "四平八稳，攻守兼备。面面俱到却少了杀招——几乎不出暴击。",
  "Cuồng Công Bộ": "狂攻步",
  "Bạo Công": "暴攻",
  "+28% Công": "+28% 攻击",
  "+8% Bạo kích": "+8% 暴击",
  "−20% Phòng thủ": "−20% 防御",
  "Lao thẳng tấn sát, bất chấp phòng bị. Hạ quái cực nhanh song thân mong manh — nên phối hút máu hoặc né để bù.": "直进抢杀，不顾防备。杀怪极快但身板脆——宜配吸血或闪避补足。",
  "Kiên Thủ Bộ": "坚守步",
  "Phòng Thủ": "防御",
  "+35% Thủ": "+35% 防御",
  "+18% Sinh Lực": "+18% 生命",
  "giảm 10% Sát Thương phải chịu": "受到伤害减少 10%",
  "−15% Công": "−15% 攻击",
  "−10% Tốc": "−10% 速度",
  "Vững như bàn thạch, ôm đòn trường kỳ không gục. Hiếm khi Trọng Thương nhưng hạ quái rất chậm — hợp cày qua đêm an toàn.": "稳如磐石，长期扛打不倒。极少重伤但杀怪很慢——适合安心挂机过夜。",
  "Tấn Tốc Bộ": "迅速步",
  "Tốc Độ & Né": "速度 & 闪避",
  "+28% Tốc": "+28% 速度",
  "14% Né đòn": "14% 闪避",
  "−10% Công": "−10% 攻击",
  "−10% Thủ": "−10% 防御",
  "Thân ảnh như chớp, lấy né tránh thay giáp trụ. Ra đòn dồn dập nhưng phòng bị mỏng — dính đòn là thấm.": "身影如电，以闪避代甲胄。出手绵密但防备单薄——中招便吃痛。",
  "Linh Xảo Bộ": "灵巧步",
  "+15% Bạo Kích": "+15% 暴击",
  "+45% Sát Thương Bạo Kích": "+45% 暴击伤害",
  "−15% Công thường": "−15% 普通攻击",
  "Dồn cả vào nhất kích trí mạng. Khi bạo kích thì kinh người, đòn thường lại nhẹ — sát thương phập phù may rủi.": "全押在致命一击上。暴击时惊人，平砍却绵软——伤害起伏全看运气。",
  "Thôn Khí Bộ": "吞气步",
  "+45% Nội Lực": "+45% 内力",
  "+70% hồi Nội Lực": "+70% 内力回复",
  "+5% Công": "+5% 攻击",
  "−12% Sinh Lực": "−12% 生命",
  "−8% Thủ": "−8% 防御",
  "Dồn chân khí vào đan điền, tung tuyệt kỹ liên hồi không cạn. Đổi lại lơ là luyện thể — máu mỏng, thủ yếu.": "真气汇聚丹田，绝技连发不竭。代价是疏于炼体——血薄防弱。",
  "Bá Đao Bộ": "霸刀步",
  "Cực Công": "极攻",
  "+38% Công": "+38% 攻击",
  "−12% Bạo kích": "−12% 暴击",
  "−28% Phòng thủ": "−28% 防御",
  "Lấy công át tất, một đao định sinh tử. Sát thương kinh người song thân tựa giấy — phải kết liễu thật nhanh hoặc phối hút máu/né để gánh.": "以攻压倒一切，一刀定生死。伤害惊人但身如纸糊——须速战速决，或配吸血/闪避撑住。",
  "Quỷ Ảnh Bộ": "鬼影步",
  "Né Tuyệt Đối": "绝对闪避",
