  "Cho linh thú ăn thẳng linh thảo — hồi Thể Lực theo bậc cây và cộng Kinh Nghiệm. Bậc càng cao, một cây càng lời với linh thú mạnh.": "直接以灵草喂灵兽 — 依草阶回复体力并增经验。草阶愈高，对强大灵兽愈划算。",
