  "Rượu này nhạt, nhưng chuyện giang hồ thì đậm.": "这酒淡，江湖事却浓。",
  "Ngồi đây nửa canh giờ, nghe được ba chuyện đáng tiền.": "在此坐了半个时辰，听得三桩值钱的事。",
  "Đao để dưới bàn, tay vẫn không rời chuôi.": "刀放桌下，手仍不离刀柄。",
  "Quán đông thế này, tất có kẻ đến không phải để uống.": "店中如此热闹，必有人来意不在酒。",
  "Mưa lớn ngoài kia, đường xuống núi chắc lầy rồi.": "外头大雨，下山的路怕是泥泞了。",
  "Ta chờ một người, người ấy trễ đã ba ngày.": "我在等一个人，那人已迟了三日。",
  "Chủ quán, thêm một vò — hôm nay không tính đường về.": "店家，再来一坛 — 今日不问归路。",
  "Giang hồ dạo này lắm kẻ mới, ít kẻ giỏi.": "近来江湖新人多，高手少。",
  "Cầm chén lên thì là bằng hữu, đặt chén xuống thì tính sau.": "举杯便是朋友，放杯再作计较。",
  "Ta không hỏi tên ngươi, ngươi cũng đừng hỏi ta.": "我不问你姓名，你也休问我。",
  "Kiếm gãy rồi, nhưng tay chưa gãy.": "剑断了，手还没断。",
  "Nghe nói có kẻ phá quan tháng trước. Chẳng biết thật hay đồn.": "听说上月有人破关。不知是真是谣传。",
  "Ngồi lâu quá, chân tê mà lòng chưa yên.": "坐得久了，腿麻而心未安。",
  "Đêm nay trăng mỏng, hợp để đi đường xa.": "今夜月薄，正宜远行。",
  "Ai trả tiền rượu thì người đó nói, quy củ ở đây là vậy.": "谁付酒钱谁说话，此处规矩如此。",
  "Ta từng thua một trận, nhớ tới giờ.": "我曾败过一场，至今记得。",
  "Chén này ta nhận. Có gì muốn hỏi, hỏi đi.": "这杯我受了。有什么要问，问吧。",
  "Rượu ngon. Kẻ mời rượu thường không mời suông.": "好酒。请酒之人，多半不白请。",
  "Được, ngươi có lòng. Ta nói ngươi nghe một chuyện.": "好，你有心。我说一桩事与你听。",
  "Đã lâu không ai mời ta. Ngồi xuống.": "许久没人请我了。坐下。",
  "Uống thì uống, nhưng đừng hỏi chuyện năm xưa.": "喝便喝，但莫问当年事。",
  "Chén đầy thì lời cũng đầy theo.": "杯满，话也跟著满。",
  "Ngươi mời khéo lắm. Ta không quen thiếu nợ.": "你这酒请得巧。我不惯欠人。",
  "Cạn. Giờ thì nghe cho kỹ.": "乾了。现在仔细听。",
  "Chuyện của ta dài, kể ra thì hết vò rượu.": "我的事说来话长，讲完只怕酒坛见底。",
  "Ta đi khắp chốn, chỉ tìm một người chưa gặp.": "我走遍四方，只为寻一个未曾谋面之人。",
  "Năm xưa ta cũng như ngươi, đứng ngoài cửa quán nhìn vào.": "当年我也如你一般，站在店门外往里看。",
  "Đừng học ta. Đường ta đi hỏng nhiều hơn nên.": "别学我。我走的路，败多成少。",
  "Muốn mạnh thì đừng vội. Vội là chết.": "想强便莫急。急则死。",
  "Ta có một chiêu chưa từng dùng. Mong đời không phải dùng tới.": "我有一招从未用过。但愿此生用不上。",
  "Kẻ mạnh không phải kẻ thắng nhiều, là kẻ còn ngồi được ở đây.": "强者不是胜得多的人，而是还能坐在这里的人。",
  "Hỏi ít thôi. Biết nhiều quá cũng là họa.": "少问些。知道太多也是祸。",
