  "Lấy nghĩa làm đầu, lấy đao làm lý.": "以义为先，以刀为理。",
  "Vào bang là huynh đệ, ra bang là người dưng.": "入帮是兄弟，出帮是路人。",
  "Không hỏi xuất thân, chỉ hỏi bản lĩnh.": "不问出身，只问本事。",
