  "Engine cờ vua thiếu hàm": "西洋棋引擎缺少函式",
  "Quân trắng đi trước, tại hạ không khách khí đâu.": "白棋先行，在下不客气了。",
  "Nước này tiền bối thấy sao?": "这一著前辈以为如何？",
  "Bàn cờ Tây Dương này lạ mắt, nhưng đạo lý vẫn thế thôi.": "这西洋棋盘看著新奇，道理却是一样。",
  "Các hạ cầm quân trắng, xin mời đi trước.": "阁下执白，请先行。",
  "Cờ nào cũng vậy, cốt ở người cầm quân.": "什么棋都一样，关键在执子之人。",
  "Ba mươi hai quân, sáu mươi tư ô, đủ cả một đời người.": "三十二子，六十四格，足抵一生。",
  "Khai cuộc thế nào là tuỳ các hạ, tại hạ tiếp hết.": "如何开局随阁下，在下全接。",
  "Mã tại hạ đã cắm vào giữa trận, các hạ liệu hồn.": "在下的马已插入阵中，阁下当心。",
  "Tượng đi chéo cả bàn, các hạ có thấy đường nó không?": "象斜行全盘，阁下看得见它的路么？",
  "Hậu mà ra sớm quá thì chỉ tổ bị đuổi thôi.": "皇后出得太早，只会被追著跑。",
  "Tốt của các hạ đi được nửa đường rồi đấy.": "阁下的兵已走到一半了。",
  "Xe hậu đã vào, các hạ đỡ nổi không?": "车后已入阵，阁下挡得住吗？",
  "Vua các hạ ngồi không yên rồi đấy.": "阁下的王坐不安稳了。",
  "Hàng tốt che vua đã thủng, còn gì che nữa?": "护王的兵阵已破，还有何可挡？",
  "Ván sau nhớ giữ hàng tốt trước vua cho kỹ.": "下局记得守好王前的兵。",
