  "<div class=\"l2-steps\"><div class=\"l2-stp\" data-go=\"1\"><span class=\"no\">1</span><span class=\"v\">Tâm Pháp</span></div><div class=\"l2-stp\" data-go=\"2\"><span class=\"no\">2</span><span class=\"v\">Kỹ Năng</span></div></div>": "<div class=\"l2-steps\"><div class=\"l2-stp\" data-go=\"1\"><span class=\"no\">1</span><span class=\"v\">心法</span></div><div class=\"l2-stp\" data-go=\"2\"><span class=\"no\">2</span><span class=\"v\">技能</span></div></div>",
