  "<div class=\"l2-step s1 on\"><div class=\"l2-sech\"><span class=\"t\">Tâm Pháp</span><span class=\"hint\">chọn 1 (hoặc bỏ trống)</span><span class=\"pick l2-tppick\">0 / 1</span></div><div class=\"l2-gw\"><div class=\"l2-g tp l2-tplist\"></div></div></div>": "<div class=\"l2-step s1 on\"><div class=\"l2-sech\"><span class=\"t\">心法</span><span class=\"hint\">选 1 (或留空)</span><span class=\"pick l2-tppick\">0 / 1</span></div><div class=\"l2-gw\"><div class=\"l2-g tp l2-tplist\"></div></div></div>",
