  "</div><div class=\"rr\"><span class=\"ntk-dot b\"></span><span class=\"rs\">Đang đi…</span></div></div></div>": "</div><div class=\"rr\"><span class=\"ntk-dot b\"></span><span class=\"rs\">落子中…</span></div></div></div>",
