  "Hữu": "右",
  "Tả": "左",
  "Chia bài đi, tay tôi đang ngứa.": "发牌吧，我手痒了。",
  "Ai cầm Ba Cơ thì mở lượt nhé.": "谁手上有红心三就先开牌。",
  "Bài bạc là chuyện nhỏ, thua keo này ta bày keo khác.": "赌牌小事，这局输了再设下局。",
  "Ngồi xuống thì đừng tính đường rút.": "既已入座，就别想著抽身。",
  "Lâu rồi mới có người dám ngồi cùng chiếu.": "许久没人敢同席而坐了。",
  "Lá Hai đây, cả bộ có mỗi một con.": "二来了，整副只此一张。",
  "Con này chắc không ai đè nổi đâu nhỉ.": "这张大概没人压得住吧。",
  "Thả lá Hai dò đường một cái.": "扔张二探探路。",
  "Tôi ra lá Hai, các vị liệu mà giữ bom.": "我出二，诸位留著炸弹吧。",
  "Bom! Cất bài đi mà tiếc.": "炸弹！收牌去心疼吧。",
  "Đợi mãi mới có chỗ thả bom.": "等了半天才有处落炸弹。",
  "Tứ quý này tôi giữ từ đầu ván đấy.": "这四条我从开局就留著。",
  "Xin lỗi, bốn con nằm sẵn trong tay rồi.": "抱歉，四张早在手里了。",
  "Thôi xong, dính bom rồi.": "完了，中炸弹了。",
  "Giấu kỹ thế cơ à.": "藏得这么深啊。",
  "Tôi tưởng cả làng hết bom rồi chứ.": "我还以为满桌都没炸弹了。",
  "Đau, bộ đó tôi tính để chạy đấy.": "疼，那套我本打算用来走牌的。",
  "Không đè nổi, tôi bỏ.": "压不住，我不要。",
  "Bài tôi kẹt, mời các vị.": "我的牌卡住了，诸位请。",
  "Bỏ lượt, để dành sức.": "过，留些力气。",
  "Nước này tôi chịu.": "这一著我认了。",
  "Tôi còn một lá thôi đấy, liệu mà chặn.": "我只剩一张了，看著点拦。",
  "Sắp hết bài rồi, ai chặn được không?": "牌快出完了，谁拦得住？",
  "Một lượt nữa là tôi trắng tay.": "再一轮我就空手了。",
  "Chạy hết rồi! Đếm bài đi các vị.": "跑光了！诸位数牌吧。",
  "Bài đẹp thì đánh kiểu gì cũng thắng.": "牌好，怎么打都赢。",
  "Tôi đi trước, bài đọng lại các vị tự tính nhé.": "我先走，剩下的牌诸位自己算。",
  "Bài đọng cả nắm, hôm nay tay tôi lạnh quá.": "剩了一大把，今日手气太冷。",
  "Bài xấu thì đành chịu, ván sau gỡ.": "牌烂只得认，下局再扳。",
  "Thua tâm phục, không kêu ca.": "输得心服，不多言。",
  "Nói ít thôi, đánh đi.": "少说，出牌。",
  "Ừ thì cứ đánh rồi biết.": "那便打过再说。",
  "Còn lâu mới tới lượt các hạ mừng.": "还轮不到阁下高兴。",
  "Hay lắm, để xem cuối ván ai cười.": "好得很，看局终谁笑。",
  "Được, tôi nghe đây.": "好，我听著。",
  "Chia bài đi.": "发牌吧。",
  "Bài này khó nhằn đấy.": "这副牌难啃。",
  "Thả bom cho nhanh.": "快扔炸弹。",
  "Ai còn lá Hai thì ra đi.": "谁还有二就出吧。",
  "Ván này tôi không nhường.": "这局我不让。",
  "Nước đó đẹp thật.": "那一著漂亮。",
  "Thua keo này bày keo khác.": "这局输了再设下局。",
  "Từ từ, để tôi tính đã.": "且慢，容我先算算。",
