  "Cây mọc đó quanh năm, hái lúc nào chẳng được.": "草木长年在此，何时采不得？",
  "Xin lão chỉ cái khắc ấy.": "请前辈指点那一刻。",
  "Chênh có bảy ngày mà đổi cả gốc rễ?": "仅差七日，根性便全变？",
