  "Gây 6 ST.": "造成6伤害。",
  "Chiêu kiếm nhập môn, thẳng tới thẳng lui. Cao thủ nào cũng khởi từ một đường kiếm mộc mạc như thế — vạn pháp quy căn.": "入门剑招，直去直回。高手皆起于这般朴拙一剑——万法归根。",
  "Quyền lộ khởi thủ, công thủ tương sinh. Chưa vội cầu chiêu lạ, trước hãy đứng cho vững tấn.": "拳路起手，攻守相生。莫急求奇招，先把桩站稳。",
  "4 ST · Suy Yếu 1.": "4伤害 · 虚弱1。",
  "2 ST ×2.": "2伤害×2。",
  "Thân pháp tuyệt thế, bước theo phương vị Dịch lý. Người đi như lướt trên sóng biếc, phiêu hốt vô định, lấy bộ pháp hóa giải kình đạo.": "绝世身法，依易理方位而行。人如掠于碧波，飘忽无定，以步法化解劲道。",
  "Rút 2 lá.": "抽2张牌。",
  "Bộ pháp nhẹ tựa thanh phong, tiến thoái theo tâm. Chân bước thảnh thơi mà chiêu thức nối liền chẳng dứt.": "步法轻若清风，进退随心。脚下从容，招式连绵不绝。",
  "Nội công chí dương chí cương, chân khí sinh sinh bất tức. Luyện thành thì bách độc bất xâm, càng chiến càng hăng, khí lực vô cùng.": "内功至阳至刚，真气生生不息。练成则百毒不侵，愈战愈勇，气力无穷。",
  "5 ST · Suy Yếu 2.": "5伤害 · 虚弱2。",
  "Kỳ thư đoạt tạo hóa, khiến quần hùng tranh nhau đổ máu. Nội công âm nhu tinh diệu, chiêu ra lặng lẽ mà đoạt hồn nhiếp phách.": "奇书夺造化，令群雄争相流血。内功阴柔精妙，出招无声却夺魂摄魄。",
  "5 ST toàn địch.": "全敌5伤害。",
  "Một chiêu quét ngang cả trận, đãng địch như đãng lá. Khí thế ngời ngời tựa thiên binh vạn mã tràn tới.": "一招横扫全阵，荡敌如荡叶。气势煌煌，恰似千军万马涌来。",
  "18 ST · Phá Giáp · Đoạn.": "18伤害 · 破甲 · 消耗。",
  "Bá đạo trấn thế của Thiên Vương Bang. Một chưởng giáng xuống nghiền non lấp bể, uy áp muôn quân, thiên hạ khiếp phục.": "天王帮镇世霸道。一掌落下碾山填海，威压万军，天下慑服。",
  "7 ST · Phá Giáp.": "7伤害 · 破甲。",
  "Gây 11 ST.": "造成11伤害。",
  "Trấn sơn tuyệt kỹ Thiếu Lâm, mười tám vị La Hán hộ trì. Quyền cương mãnh hùng hồn, một đấm ra như sấm động, đủ hàng ma vệ đạo.": "少林镇山绝技，十八罗汉护持。拳刚猛雄浑，一拳出如雷动，足以降魔卫道。",
  "Trượng pháp do Đạt Ma tổ sư truyền lại, cương trung hữu nhu. Một trượng quét ngang vừa khắc địch vừa lập thế thủ.": "达摩祖师所传杖法，刚中有柔。一杖横扫，既克敌又立守势。",
  "Bí điển tẩy tủy dịch cân của Thiền môn. Luyện thấu thì gân cốt đổi mới, phàm thai thoát cốt, khí lực tăng tiến chẳng cùng.": "禅门洗髓易筋秘典。练透则筋骨更新，脱胎换骨，气力增进无穷。",
  "Giảm ½ đòn kế · rút 1.": "下次受击减半 · 抽1。",
  "4 ST ×2 · rút 1.": "4伤害×2 · 抽1。",
  "Rút 1.": "抽1张牌。",
  "5 ST · rút 1.": "5伤害 · 抽1。",
  "3 ST ×3 · rút 1.": "3伤害×3 · 抽1。",
  "6 ST ×3 · rút 2 · Giảm ½ đòn · Đoạn.": "6伤害×3 · 抽2 · 受击减半 · 消耗。",
  "3 ST · Độc 4.": "3伤害 · 中毒4。",
  "Đường Môn đất Thục danh chấn thiên hạ vì ám khí. Mũi tiêu tẩm độc bắn ra vô thanh vô tức, thấy máu là phong hầu.": "蜀地唐门以暗器名震天下。淬毒镖射出无声无息，见血封喉。",
  "3 ST ×4 · Độc 2.": "3伤害×4 · 中毒2。",
  "Độc 3 · rút 2.": "中毒3 · 抽2。",
