  "4 ST · Độc 4.": "4伤害 · 中毒4。",
  "8 ST · Độc 3.": "8伤害 · 中毒3。",
  "Tà công nghịch thiên của Ma Giáo, hút cạn nội lực người khác nạp vào mình. Uy lực kinh người, song dị chủng chân khí xung đột, sớm muộn phản phệ.": "魔教逆天邪功，吸尽他人内力纳为己有。威力惊人，然异种真气冲突，迟早反噬。",
  "18 ST · tự −5 HP · Đoạn.": "18伤害 · 自身−5生命 · 消耗。",
  "5 ST · hút máu · Suy Yếu 1.": "5伤害 · 吸血 · 虚弱1。",
  "5 ST · hút máu.": "5伤害 · 吸血。",
  "6 ST · tự −3 HP.": "6伤害 · 自身−3生命。",
  "9 ST · tự −3 HP.": "9伤害 · 自身−3生命。",
  "10 ST · hút máu · tự −4 HP.": "10伤害 · 吸血 · 自身−4生命。",
  "Nga Mi": "峨嵋",
  "Hồi 8 HP.": "回复8生命。",
  "Chân truyền Cửu Dương của phái Nga Mi. Vận công điều tức thì nội thương tự khỏi, ôn dưỡng sinh cơ, trụ được đường dài.": "峨嵋派九阳真传。运功调息则内伤自愈，温养生机，久战不衰。",
  "Hồi 4.": "回复4。",
  "5 ST · hồi 3.": "5伤害 · 回复3。",
  "Hồi 10 · rút 1.": "回复10 · 抽1。",
  "Gây 9 ST.": "造成9伤害。",
  "Kiếm tông Hoa Sơn lấy khí ngự kiếm, chiêu thức tiêu sái. Một đường lăng lệ như gió núi, chính khí lẫm nhiên soi tỏ giang hồ.": "华山剑宗以气御剑，招式潇洒。一剑凌厉如山风，正气凛然照彻江湖。",
  "4 ST · rút 1.": "4伤害 · 抽1。",
  "4 ST ×5 · rút 2 · Đoạn.": "4伤害×5 · 抽2 · 消耗。",
  "6 ST · rút 1.": "6伤害 · 抽1。",
