  "8 ST toàn địch · Suy Yếu 3 · Choáng 1 · Đoạn.": "全敌8伤害 · 虚弱3 · 晕眩1 · 消耗。",
  "8 ST · Choáng 1.": "8伤害 · 晕眩1。",
