  "5 ST · Bỏng 2×3.": "5伤害 · 灼烧2×3。",
  "6 ST toàn địch · Bỏng 2×3.": "全敌6伤害 · 灼烧2×3。",
  "Bỏng 4×3 toàn địch · Đoạn.": "全敌灼烧4×3 · 消耗。",
  "2 ST · Bỏng 1×3.": "2伤害 · 灼烧1×3。",
  "3 ST · Bỏng 2×3.": "3伤害 · 灼烧2×3。",
