  "8 ST ×2 · Đoạn.": "8伤害×2 · 消耗。",
  "Đánh 3 × 3 ST.": "攻击3次 × 3伤害。",
  "Kiếm phổ tà môn nhanh đến quỷ khốc thần sầu. Ba nhát liền như một, ai thấy cũng lạnh gáy — nhưng luyện thì phải trả giá đắt.": "邪门剑谱，快得鬼哭神愁。三刀连如一刀，见者皆脊背生寒——然修习代价极重。",
  "11 ST · tự −5 HP.": "11伤害 · 自身−5生命。",
  "22 ST · tự −8 HP · Đoạn.": "22伤害 · 自身−8生命 · 消耗。",
  "8 ST · tự −3 HP.": "8伤害 · 自身−3生命。",
