  "14 ST · Phá Giáp · tự −4 HP.": "14伤害 · 破甲 · 自身−4生命。",
  "Trương chân nhân ngộ đạo bên suối, thấy nước chảy đá mòn mà thành quyền. Một vòng thái cực bao la, dĩ tĩnh chế động, tứ lạng bạt thiên cân.": "张真人溪畔悟道，见水滴石穿而成拳。一圈太极浩渺，以静制动，四两拨千斤。",
  "6 ST · Suy Yếu 1.": "6伤害 · 虚弱1。",
  "16 ST · Choáng 1 · Đoạn.": "16伤害 · 晕眩1 · 消耗。",
