  "Lợi Nhận": "利刃",
  "Thẻ Công đầu tiên mỗi lượt gây thêm 3 sát thương.": "每回合首张攻击牌额外造成3点伤害。",
  "Thẻ gây Độc áp dụng thêm 2 Độc.": "造成中毒的牌额外施加2层中毒。",
  "Độc hành vô ảnh, sát nhân vô thanh. Kẻ này không trọng cường công, chỉ lấy kỳ độc nhập mạch, loạn khí, tổn thần. Một khi độc tức đã thấm kinh lạc, sinh tử liền khó thoát khỏi lòng bàn tay.": "独行无影，杀人无声。此人不重强攻，只以奇毒入脉，乱气损神。毒息一旦渗入经络，生死便难逃掌心。",
  "Đầu lượt, nhận 3 Hộ Thể.": "回合开始时获得3点护体。",
  "Đăng Tiên 1 lần": "登仙1次",
  "Thẻ gây Suy Yếu áp dụng thêm 1 Suy Yếu.": "造成虚弱的牌额外施加1层虚弱。",
