  "Cho ta nếm thử một ngụm là biết.": "让我尝一口便知。",
  "Chẳng trao gì, sao lão còn gọi ta tới?": "什么都不给，老丈何必唤我来？",
  "Chỉ có gõ thôi sao?": "就只是敲打而已？",
  "Chỉ cần thẳng thôi sao? Ta tưởng nghề mộc phải cầu kỳ.": "只求一个直字？我还以为木工须得精巧。",
  "Chỉ nghe tiếng cuốc của mình.": "只听见自己的锄声。",
  "Chỗ hiểm nằm ở vị thuốc nào?": "险处在哪一味药？",
