  "Con dao bếp mẻ này...?": "这把缺口的菜刀……？",
  "Con e mình chưa đủ tâm.": "弟子恐怕心意未足。",
  "Con gõ tiếp đây, không dám than.": "弟子继续敲，不敢叫苦。",
  "Con hiểu rồi. Đưa con cái cuốc.": "弟子明白了。把锄头给我。",
  "Con hứa sẽ giữ nghề.": "弟子答应守住这门手艺。",
  "Con khắc cốt lời lão.": "老丈之言，弟子刻骨。",
  "Con muốn học cái nghề nuôi được thân.": "弟子想学一门能养活自己的手艺。",
  "Con muốn học nghề, xin lão chỉ dạy.": "弟子想学艺，请老丈指点。",
  "Con nghe đây.": "弟子听著。",
  "Con ngồi nghe lão.": "弟子坐下听老丈说。",
  "Con phải rèn cái gì để không phụ lão?": "弟子该锻什么，才不负老丈？",
  "Con sẽ rèn nên danh với cây búa này.": "弟子必以此锤锻出名堂。",
  "Con vẫn chưa hiểu 'đúng thớ'.": "弟子仍不懂何谓『顺纹』。",
  "Con xin nghe theo lời lão.": "弟子谨遵老丈之言。",
  "Con xin nhận.": "弟子领受。",
  "Con... nhận sao được cây búa của lão?": "弟子……怎敢受老丈的锤？",
  "Con… chưa từng nghe.": "弟子……从未听闻。",
  "Cuốc thì tầm thường quá.": "锄头未免太平常了。",
  "Cái người ta không thấy... lại là cái giữ cả tòa nhà.": "人所不见之处……才撑住整座屋。",
  "Câu hỏi nào ta cũng không ngại.": "任何问题我都不怕。",
  "Cây chịu ngã, con mới bổ.": "树肯倒，我才劈。",
  "Cây cầu đã gãy — tiền bối vẫn giữ cây thước đó?": "桥已断 — 前辈仍留著那把尺？",
  "Cây thì nói được gì?": "树能说什么话？",
  "Còn lão?": "那老丈呢？",
  "Còn sợi dây kia dùng làm gì?": "那条绳子又作何用？",
  "Gãy? Cầu của một truyền nhân Lỗ Ban mà cũng gãy sao?": "断了？鲁班传人所造之桥也会断？",
  "Gõ mãi một miếng, có ích gì đâu?": "一块铁敲个没完，有何益处？",
  "Hai cây này… giống hệt nhau.": "这两棵树……一模一样。",
  "Hai thứ này có gì đặc biệt?": "这两样有何特别？",
  "Khe hở đó là gì?": "那道缝隙是什么？",
  "Kéo lên đi! Cả đời lão chờ nó mà!": "拉上来吧！老丈等了一辈子！",
  "Làm sao biết lúc nào phải lùi?": "如何知道何时该退？",
  "Lão bỏ lại thứ gì?": "老丈留下了什么？",
  "Lão cứ hỏi.": "老丈尽管问。",
  "Lão hối hận?": "老丈后悔了？",
