  "Lão trao ta cái gì?": "老丈给我什么？",
  "Lão trao ta thứ gì?": "老丈交我何物？",
  "Lão trao đèn… là trao điều gì?": "交灯……是交什么？",
  "Lão trượng, chỉ ta cách đào đi.": "老丈，教我如何挖。",
  "Lão từng nấu bữa ấy sao?": "老丈当年煮过那顿饭？",
  "Lão đau nhiều lắm sao?": "老丈很疼吗？",
  "Lão đã đào quá sâu?": "老丈挖得太深了？",
  "Lão đã đốn nó?": "老丈砍了它？",
  "Lão để lại nhiều hơn thế chứ.": "老丈留下的岂止这些。",
  "Lão định thôi gõ rồi ư?": "老丈打算不再敲了么？",
  "Lò sẽ không tắt đâu lão.": "炉子不会熄的，老丈。",
  "Lòng người thì đo bằng gì?": "人心又以何物来量？",
  "Một cái cuốc thì học được gì?": "一把锄头能学到什么？",
  "Một cây cầu thì sợ gì mưa?": "一座桥怕什么雨？",
  "Một tay thì vỗ sao thành tiếng được.": "一个巴掌拍不响。",
  "Nay ta cũng có một mạng đang nguy trong tay.": "如今我手上也有一条垂危的人命。",
  "Nghe cây… hóa ra là nghe chính mình.": "听树……原来是听自己。",
  "Nghe nói lão là tay búa giỏi nhất vùng.": "听说老丈是这一带最好的铁匠。",
  "Nghe nói lão đã đắc đạo. Ta tới học.": "听说老丈已得道。我来求学。",
  "Nghe được rồi thì sao?": "听见了又如何？",
  "Nghỉ tay đi lão, sắt để mai.": "歇手吧老丈，铁留到明日。",
