  "rắn rỏi nổi lên, da thịt loé ánh kim.": "坚硬崛起，皮肉闪出金光。",
  "sinh sôi, độc vụ phảng phất.": "滋生蔓长，毒雾隐约弥漫。",
  "sắc lạnh, lông da cứng tựa giáp sắt.": "锐利冰冷，皮毛硬如铁甲。",
  "thiêu đốt, sát khí ngùn ngụt.": "焚烧不止，杀气腾腾。",
  "trầm lạnh cuồn cuộn dâng lên.": "沉寒滚滚涌起。",
  "trầm trọng vững như non.": "沉重稳如山岳。",
  "xanh rì, sinh cơ lẫn độc khí đan cài.": "青翠欲滴，生机与毒气交织。",
  "âm trầm trỗi dậy.": "阴沉升腾。",
  "# # — ngươi lách mình tránh gọn, không hề hấn gì.": "# # — 你侧身避开，毫发无伤。",
  "# # — ngươi lãnh trọn": "# # — 你硬受",
  "# #, bổ vào ngươi": "# #，劈中你造成",
  "# #, ngươi đỡ không trọn, mất": "# #，你格挡不全，失去",
  "# #, nhưng ngươi thân pháp như mây trôi, nhẹ nhàng né thoát.": "# #，然你身法如行云，轻巧闪脱。",
  "# bốc cháy phừng phừng, tổn": "#烈焰腾身，损",
  "# gầm lên, toàn thân bốc cháy rừng rực, ngưng tụ một thân": "#咆哮一声，浑身烈焰腾腾，凝聚一身",
  "# khí hộ thể của địch dày như thành, gạt đi #% uy lực.": "敌人的#气护体厚如城墙，卸去 #% 威力。",
  "# kình quán vào #, hao": "#劲贯入#，耗",
