  "# lãnh trọn": "#硬受",
  "# lãnh trọn một đạo # kình, tổn": "#硬受一道#劲，损",
  "# mắt đỏ như than, vận khởi": "#双目赤如炭火，运起",
  "# ngưng tụ": "#凝聚",
  "# thân hình một thoáng nhoè đi, đòn của ngươi chém trượt vào khoảng không.": "#身形一瞬模糊，你这一击斩入虚空。",
  "# toả": "#散发",
  "Cỏ cây quanh # rạp xuống, một thân": "#四周草木伏倒，一身",
  "Hàn khí buốt giá lan toả, # ngưng một thân": "刺骨寒气蔓延，#凝起一身",
  "Ngươi ra đòn quá lộ, # đã kịp lùi khỏi tầm.": "你出招过于明显，#已及时退出攻击范围。",
  "Thân nó vốn nhuốm # khí, kình # rót vào như đá chìm biển — chặn mất #%.": "它本身便浸染#气，#劲灌入猶如石沉大海 — 被挡去 #%。",
  "hỏa khí cuồn cuộn nuốt lấy #, hao": "火气翻卷吞没#，耗",
  "ngươi đảo bộ phiêu hốt, đòn # của # đánh vào khoảng không.": "你步法飘忽，#的#招打入虚空。",
  "sát thương # lên #": "#伤害于#",
  "sát thương Hỏa lên mình #": "火伤害于#",
