  "✅ # rống lên thê lương rồi đổ gục. Hạ sau #s · Sinh Lực còn #% · +# EXP#.": "✅ #哀嚎一声倒地。#秒内击倒 · 生命剩 #% · +# 经验#。",
  "✅ Một chiêu định đoạt, # tắt thở đổ rạp. (#s · còn #% · +# EXP#)": "✅ 一招定胜负，#气绝倒地。（#秒 · 剩 #% · +# 经验#）",
  "💀 # tung đòn cuối, ngươi đỡ không nổi, thổ huyết ngã quỵ — TRỌNG THƯƠNG!": "💀 #使出最后一击，你挡不住，吐血倒地 — 重伤！",
