  "một bàn mỹ vị danh chấn #": "一桌美馔名震#",
  "ngao du #, gặp một đoạn kỳ duyên hiếm có": "遨游#，遇一段难得奇缘",
  "nơi # câu được": "于#钓得",
  "thiền tọa nơi #, đạo tâm thông triệt": "于#禅坐，道心通透",
  "tinh thông #, được muôn người kính nể": "精通#，为万人敬重",
  "# có duyên gặp gỡ tông môn ngươi, truyền lại một phần tâm đắc võ học cùng chút lễ vật giang hồ làm quà kết giao.": "#有缘造访你的宗门，传下一部分平生武学心得，另附些许江湖礼物以结交情。",
  "# là mối họa tà đạo đang bị giang hồ truy nã. Tông môn đủ thực lực ra tay trừ gian sẽ được trọng thưởng uy danh.": "#是遭江湖通缉的邪道祸患。实力足够出手除奸的宗门将获重赏威名。",
  "# nghe danh tông phong của ngươi, ngỏ ý đầu nhập làm đệ tử, mang theo sở học bình sinh truyền lại cho tông môn. Chỉ tông môn đủ uy vọng mới giữ chân nổi cao nhân — thu nhận thì danh chấn giang hồ.": "#闻你宗门之风，有意投入门下为弟子，将平生所学传与宗门。唯有威望足够的宗门才留得住高人 — 收下便名震江湖。",
  "Bóng tiền nhân # quá lớn — ta phải bước ra khỏi cái bóng ấy, hay nương theo nó?": "前人#的影子太大 — 我该走出那道影子，还是依傍著它？",
  "Bế quan # ngày, công lực lại tiến thêm một tầng.": "闭关 # 日，功力又进一层。",
  "Kế thừa y bát #, nối chí tiền nhân # — quyết không để danh môn lụi tàn trong tay mình.": "承继#的衣钵，继前人#之志 — 决不让名门在自己手中衰败。",
  "Kết oán với # 「#」 — #.": "与# 「#」结怨 — #。",
  "Luận võ bại dưới tay # 「#」, đối thủ #.": "论武败于# 「#」之手，对手#。",
  "Luận võ thắng # 「#」 — #.": "论武胜过# 「#」 — #。",
  "Tiền nhân # 「#」 tạ thế — # kế thừa y bát #, gánh vác sư môn.": "前人# 「#」辞世 — #承继#的衣钵，扛起师门。",
  "Truyền nhân tân tiến của #, kế thừa y bát #. Chưa có ân oán gì với ngươi — nhưng cái bóng tiền nhân buộc hậu bối phải sớm chọn bạn hay thù.": "#新晋的传人，承继#的衣钵。与你尚无恩怨 — 然前人的影子逼得后辈须及早择友或择敌。",
  "Truyền nhân đời thứ nhất của #. Khi tiền bối # 「#」 tạ thế, # được chọn kế thừa y bát, gánh trên vai cả thanh danh lẫn ân oán của sư môn. Tuổi trẻ chí lớn, còn non kinh nghiệm nhưng căn cơ đã vững — giang hồ đang chờ xem hậu bối có giữ nổi ngọn đèn tổ truyền.": "#的第一代传人。前辈# 「#」辞世之时，#获选承继衣钵，肩上扛起师门的声名与恩怨。年少志大，经验尚浅而根基已稳 — 江湖正等著看这后辈守不守得住那盏祖传的灯。",
  "Tuyệt học trấn phái # truyền tới tay hậu bối — uy lực còn đó, hỏa hầu chờ ngày viên mãn.": "镇派绝学#传到后辈手中 — 威力猶在，火候尚待圆满之日。",
  "Tình cờ đắc một mảnh tàn quyển nơi #.": "偶得一片残卷于#。",
  "Ác chiến nơi #, trảm một yêu thú khét tiếng.": "于#恶战，斩一头声名狼借的妖兽。",
  "Đại chiến với # 「#」 tại # — #.": "与# 「#」大战于# — #。",
  "Cơ quan kích phát, ngươi cậy": "机关触发，你倚仗",
  "Cổ rương khoá chặt, phá không nổi mà dính phản phệ — tổn": "古箱锁死，破之不开反遭反噬 — 损",
  "Gặp kỳ ngộ giữa đường — nhặt thêm chiến lợi phẩm, sinh lực vẹn nguyên.": "途中遇奇缘 — 多拾战利品，生命无损。",
  "Sinh lực cạn kiệt, ngươi buộc phải": "生命耗尽，你只得",
  "Trúng cạm bẫy cơ quan, né không kịp — tổn": "中了机关陷阱，闪避不及 — 损",
  "giáng thế! Tử chiến hạ gục — hao": "降世！死战击倒 — 耗",
  "lao ra cản đường — ngươi đánh dạt, hao": "冲出拦路 — 你将其击退，耗",
  "né gọn — bình an vô sự.": "俐落闪过 — 平安无事。",
  "quá mạnh, sinh lực đã cạn — đành": "太强而生命已尽 — 只得",
  "trấn giữ tầng sâu — ác chiến hạ gục, hao": "镇守深层 — 恶战击倒，耗",
