  "ập tới, # thâm hậu chống đỡ ung dung — chỉ hao": "袭来，你深厚的#从容抵住 — 只耗",
  "trễ": "迟",
  "tệ nhất": "最差",
  "→ Nếu là chữ PHỒN THỂ mà đòi Ma Shan Zheng thì vô ích: font đó chỉ có giản thể.": "→ 若为繁体字而指定 Ma Shan Zheng 则无用：该字型只有简体。",
  "# thi triển 〈#〉, #": "#施展〈#〉，#",
  "# vận 〈#〉 #": "#运起〈#〉 #",
  "Hiệp #: # dốc toàn lực một chiêu định thắng bại — # gục xuống nhận thua.": "第 # 回合：#倾尽全力一招定胜负 — #倒地认输。",
  "# bắt đầu lĩnh ngộ 「#」 (#h).": "#开始领悟「#」（#小时）。",
  "# bế quan nghiền ngẫm, lĩnh ngộ thành công 「#」!": "#闭关钻研，成功领悟「#」！",
  "# bị Giới Luật Đường trách phạt mà trong lòng bất phục, ngầm sinh oán khí.": "#遭戒律堂责罚而心中不服，暗生怨气。",
  "# bị phạt nhưng sinh bất phục — coi chừng hậu họa.": "#受罚却不服 — 慎防后患。",
  "# chịu Giới Luật Đường răn dạy, gột tâm ma tịnh đạo — sơn môn thêm nghiêm cẩn.": "#受戒律堂训诫，涤魔净道 — 山门更为严谨。",
  "# gắng gượng đón thiên lôi, song đến đạo thứ bảy thì chân nguyên cạn kiệt, hộc một ngụm máu tươi ngã quỵ giữa kiếp vân. Mây sét tan đi, để lại y thoi thóp trong vũng máu — đạo cơ chấn động, tâm ma quấy thêm một tầng. Lần này chưa thành, nhưng mạng còn thì còn cơ hội.": "#强撑迎接天雷，然至第七道时真元耗竭，喷出一口鲜血倒在劫云之下。雷云散去，只留他奄奄一息躺在血泊里 — 道基震动，心魔又搅深一层。此番未成，然命在便还有机会。",
  "# hết ô võ học (trần # theo cảnh giới).": "#武学栏位已满（上限 # 依境界而定）。",
  "# khởi hành lịch luyện (#h).": "#启程历练（#小时）。",
  "# lịch luyện trở về, mang theo #.": "#历练归来，带回#。",
  "# mãn khóa thính giảng trở về, tư chất đã chạm giới hạn.": "#听讲期满而归，资质已达极限。",
  "# phục một viên #, đột phá #!": "#服下一枚#，突破#！",
  "# thính giảng đắc ngộ, trần tư chất nới rộng — vươn tới #.": "#听讲得悟，资质上限拓宽 — 达至#。",
  "# tu vi viên mãn #, lâm Bình Cảnh — chờ đột phá đại cảnh.": "#修为圆满于#，临瓶颈 — 待突破大境界。",
  "# vào Giảng Đạo Đường thính giảng (#h).": "#进讲道堂听讲（#小时）。",
  "# vừa bị răn, đang tĩnh tâm.": "#刚受训诫，正在静心。",
  "# vừa tỉ thí, đợi hồi sức.": "#方才比试，正待回气。",
  "# đã thông 「#」.": "#已通「#」。",
  "# đã được răn dạy · tâm ma −##.": "#已受训诫 · 心魔 −##。",
  "# đêm khuya tâm ma quấy nhiễu, tự toạ thiền áp chế — đạo tâm gợn sóng (#).": "#深夜遭心魔扰动，自行坐禅压制 — 道心起波澜（#）。",
  "# đạo tâm trong sáng, không cần răn dạy.": "#道心清明，无须训诫。",
  "# độ # thất bại — đạo cơ chấn động, may giữ được mạng, lui về tĩnh dưỡng dưỡng thương.": "#渡#失败 — 道基震动，幸而保命，退回静养疗伤。",
  "# đột phá #!": "#突破#！",
