  "Dược Viên chưa đủ bậc trồng #.": "药园等级不足，无法种植#。",
  "Hết lò (#/#) — đợi mẻ xong hoặc nâng Y Quán.": "丹炉已满（#/#） — 等一炉炼完或升级医馆。",
  "Hết lượt đổi lứa hôm nay (#/#).": "今日更换名额已用尽（#/#）。",
  "Hợp nhất # bí kíp # — lĩnh hội 「#」 (#)!": "合并 # 部#秘笈 — 领会「#」（#）！",
  "Hợp nhất thành 「#」": "合并为「#」",
  "Khởi lò luyện # (#h).": "起炉炼制#（#小时）。",
  "Kiếp vân cuồn cuộn vần vũ trên đỉnh sơn môn, chín đạo thiên lôi nối nhau giáng xuống. # đứng thẳng giữa biển sét, để mặc lôi quang xé da nứt thịt mà thần hồn bất động. Đạo sấm cuối cùng dứt, mây tan trăng tỏ — # bước ra khỏi vùng cháy xém, hào quang # rạng ngời. Độ kiếp đại thành!": "劫云翻卷于山门之巅，九道天雷接连落下。#挺立于雷海之中，任雷光撕肤裂肉而神魂不动。最后一道雷声止息，云散月明 — #自焦土之中步出，#的光华灿然。渡劫大成！",
  "Luận Võ Đường: # tỉ thí # — # #.": "论武堂：#与#比试 — # #。",
  "Thiếu # (cần #).": "缺#（需 #）。",
  "Thiếu # (luyện ở Y Quán).": "缺#（于医馆炼制）。",
  "Thiếu Hồn Thạch (cần #).": "缺魂石（需 #）。",
  "Thiếu Điểm Đấu Giá (cần #).": "缺拍卖点（需 #）。",
  "Thu nhận # (#) vào môn.": "收#（#）入门。",
  "Tặng lễ # · +# giao tình": "赠礼# · +# 交情",
  "Y Quán cần Bậc # để luyện #.": "医馆需达 # 阶方能炼制#。",
  "Y Quán xuất lò một viên #.": "医馆出炉一枚#。",
  "Đoạt 「#」": "夺得「#」",
  "Đã tận Giảng Đạo (+# trần).": "讲道已尽（+# 上限）。",
  "Đã đạt trần +# — nâng Luyện Khí Các để rèn sâu hơn.": "已达上限 +# — 升级炼器阁方能锻得更深。",
  "Đãi Khách Các tặng trọng lễ cho # — giao tình thêm khăng khít.": "待客阁致送重礼予# — 交情更为亲厚。",
  "Đạo thứ chín thiên lôi giáng xuống, # vận tận chân nguyên gắng chống. Một tiếng nổ kinh thiên — thân ảnh tan vào ánh sét trắng loà, chỉ còn lại làn tro mỏng tản trong gió núi. Hồn phi phách tán, đạo tiêu ngọc nát, # đã vĩnh viễn không còn. Sơn môn chìm trong tang tóc, một nén tâm hương tiễn đưa.": "第九道天雷落下，#耗尽真元强行相抗。一声惊天巨响 — 身影没入惨白雷光之中，只余一缕薄灰散于山风。魂飞魄散，道消玉碎，#已永远不在。山门陷入哀恸，一炷心香相送。",
  "Đấu Giá Hội: đoạt được bí kíp 「#」 về Tàng Thư Lâu.": "拍卖会：拍得秘笈「#」归藏书楼。",
  "Đổi lứa mới · -# Hồn Thạch (#/#)": "更换新一批 · -# 魂石（#/#）",
  "★ # kết minh với tông môn ngươi — đồng khí liên chi, đồng minh giang hồ!": "★ #与你的宗门结盟 — 同气连枝，江湖同盟！",
  "★ # phục một viên #, đột phá Đắc Đạo — chờ ngươi định đoạt tiền đồ.": "★ #服下一枚#，突破得道 — 待你裁定前程。",
  "★ # vượt #, độ kiếp thành công đột phá # — thiên lôi tán, đạo thành, danh chấn sơn môn!": "★ #渡过#，渡劫成功突破# — 天雷散去，道成，名震山门！",
  "★ # đắc đạo Xuất Sư, vân du thiên hạ — danh chấn giang hồ, do Tông Môn ngươi đào tạo.": "★ #得道出师，云游天下 — 名震江湖，出自你的宗门所育。",
  "☍ # độ # thất bại — thiên lôi thiêu thân, hồn phi phách tán, đạo tiêu ngọc nát. Cả sơn môn cử tang.": "☍ #渡#失败 — 天雷焚身，魂飞魄散，道消玉碎。全山门举哀。",
  ". Cái tên ấy nặng lắm.": "。那个名字很沉。",
  ". Ngươi nghe qua chưa?": "。你听过么？",
