  "Có kẻ vỗ ngực nói đã thắng": "有人拍胸脯说已胜过",
  "Có kẻ đụng phải": "有人撞见",
  "Có đoàn tiêu đi ngang": "有一趟镖队路过",
  "Cửa ải": "关隘",
  "Dấu chân": "脚印",
  "Giếng cổ ở": "古井位于",
