  ". Hai đường thưởng dùng chung hệ số.": "。两条奖励路径共用同一系数。",
  ". Nhờ vậy thắng bài không sinh ra Bạc — các trò này cách ly khỏi kinh tế chính, không ảnh hưởng cân bằng cày cuốc.": "。因此赢牌不会产生银两 — 这些牌戏与主经济隔离，不影响刷怪平衡。",
