  "Nhịp # giây một trận, diễn tự động.": "每 # 秒一战，自动演算。",
  "Trong đó có": "其中包含",
  "Truy Nã chụp mốc số quái đã hạ tại thời điểm": "通缉令会在此刻撷取已击杀妖兽数：",
