  "Tài khoản #… sẽ không đẩy save lên được nữa. Họ vẫn chơi ngoại tuyến bình thường và KHÔNG được báo là đã bị khoá.": "帐号 #……将无法再上传存档。他们仍可照常离线游玩，且不会被告知已遭封锁。",
