  "★ # đầu nhập tông môn!": "★ #投入宗门！",
  "Bậc cao nhất; cần đồ phổ, nguyên liệu hiếm và # Bạc": "最高阶；需图谱、稀有材料与 # 银两",
  "Mùa # ngày; hạng vùng cho buff nghề.": "赛季 # 天；地域名次提供职业增益。",
  "Trần kháng #; Tâm Pháp cho sẵn # hệ mình.": "抗性上限 #；心法直接给予 # 点本系。",
  "bộ; dòng ẩn mở ở mốc 3, 5, 7 món.": "套；隐藏词条于 3、5、7 件时开启。",
  "loại dòng phụ; # bậc thỏi cường hoá.": "种副词条；强化用锭共 # 阶。",
  "ô công cụ; cộng thẳng vào hiệu suất nghề.": "个工具格；直接计入职业效率。",
  "# bế quan đã ba ngày không xuất. Ngươi đẩy cửa thạch thất: y ngồi giữa vũng nến chảy, mắt nhắm nghiền mà lệ máu rỉ hai bên thái dương, miệng lẩm nhẩm những lời chẳng phải của mình. Tâm ma 「#」 ủ bấy lâu nay phá phong trỗi dậy — kinh mạch gào thét, đạo tâm rạn như băng tiết xuân. Một niệm sai, bao năm khổ tu hóa tro bụi; một niệm vững, kiếp nạn lại hóa cơ duyên. Chưởng Môn, ngươi định liệu thế nào?": "#闭关已三日未出。你推开石室之门：他坐在一滩烛泪之中，双目紧闭而血泪自两鬓渗出，口中喃喃著并非自己的话语。积蓄已久的心魔「#」破封而起 — 经脉嘶号，道心裂如春初之冰。一念之差，多年苦修化为灰烬；一念之坚，劫难反成机缘。掌门，你意下如何？",
  "Giang hồ còn nhớ tên #; bao giờ họ mới nhớ tên ta?": "江湖仍记得#之名；何时才会记得我的名字？",
  "Hiệp #: ngũ hành tương khắc phát uy — #; #.": "第 # 回合：五行相克显威 — #；#。",
  "Hiệp #: võ học khắc chế lẫn nhau — #; #.": "第 # 回合：武学互相克制 — #；#。",
  "Tông Môn dùng để chiêu mộ và bồi dưỡng đệ tử; Bang Phái dùng cho tranh đấu và hoạt động tập thể. Hai hệ thống có vai trò riêng, không thay thế cho nhau.": "宗门用于招募与培养弟子；帮派用于争斗与集体活动。两套系统各司其职，不能互相取代。",
  "Băng tâm vô cấu, đạo niệm bất động. Trước vạn chiêu biến hóa vẫn tĩnh như hàn đàm, trước sát khí ngập trời vẫn lạnh tựa tuyết lĩnh. Tâm càng tĩnh, ý càng minh; ý càng minh, sát cơ càng chuẩn.": "冰心无垢，道念不动。面对万招变化仍静如寒潭，面对漫天杀气仍冷似雪岭。心愈静则意愈明；意愈明则杀机愈准。",
  "Luyện thể thành cương, huyết nhục hóa thiết. Ngoại lực nan xâm, đao binh bất phá. Thân như kim thạch, khí trấn sơn hà; lâm trận càng lâu, hộ thể càng thịnh.": "练体成刚，血肉化铁。外力难侵，刀兵不破。身如金石，气镇山河；临阵愈久，护体愈盛。",
  "Nhất khí quy nguyên, vạn pháp quy tông. Không chấp quyền chưởng, chẳng nệ binh khí; khí vận chu thiên, thế sinh vô cực. Một hơi chân khí chưa tuyệt, càn khôn vẫn còn khả chuyển.": "一气归元，万法归宗。不执拳掌，不拘兵器；气运周天，势生无极。只要一息真气未绝，乾坤仍可扭转。",
  "Nộ hỏa tàng tâm, chiến ý nhập cốt. Càng bị áp chế, hung khí càng thịnh; càng lâm tuyệt cảnh, sát lực càng cuồng. Một niệm phẫn khởi, phá trận khai sinh lộ.": "怒火藏心，战意入骨。愈受压制，凶气愈盛；愈临绝境，杀力愈狂。一念愤起，破阵开生路。",
  "Vô môn vô phái, độc bộ thiên nhai. Nhất kiếm tùy thân, bán sinh phong trần. Kiếm vị xuất, sát cơ tiên khởi; hàn quang nhất thiểm, thắng phụ dĩ phân.": "无门无派，独步天涯。一剑随身，半生风尘。剑未出鞘，杀机先起；寒光一闪，胜负已分。",
  "Bậc cao nhất; cần đồ phổ, nguyên liệu hiếm và": "最高阶；需图谱、稀有材料与",
  "loại dòng phụ;": "种副词条；",
  "ngày; hạng vùng cho buff nghề.": "天；地域名次提供职业增益。",
  "Linh Thạch có thời lượng hoạt động; hết viên này thì tự đốt viên cùng loại kế tiếp. Hết sạch thì việc vẫn chạy, chỉ mất phần cộng thêm.": "灵石有其运作时长；一枚烧尽便自动接烧同类的下一枚。全部用尽后工作仍会进行，只是少了加成。",
  "loại; Thức Tỉnh mở thêm bị động từ": "种；觉醒可再开启被动，自",
